export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "rubric", "text": "Оглавление"},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "О терпении болезней и несчастий"},
  {"id": "ru-mol-0003", "section": "service", "who": "rubric", "text": "^ Праведному Иову Многострадальному"},
  {"id": "ru-mol-0004", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:1"},
  {"id": "ru-mol-0005", "section": "service", "who": "rubric", "text": "Память праведного Твоего Иова, Господи, празднующе,/ тем Тя молим:/ избави нас от наветов и сетей лукавого диавола// и спаси души наша, яко Человеколюбец."},
  {"id": "ru-mol-0006", "section": "service", "who": "reader", "text": "Перевод: Память праведного Твоего Иова, Господи, празднуя, потому Тебя молим: избавь нас от клеветы и сетей лукавого диавола и спаси души наши, как Человеколюбец."},
  {"id": "ru-mol-0007", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Яко истинен и праведен, Богочестив и непорочен,/ освящен же явлься всеславне, Божий угодниче истинный,/ просветил еси мир в терпении твоем, терпеливейший и доблейший.// Темже вси, Богомудре, память твою воспеваем."},
  {"id": "ru-mol-0009", "section": "service", "who": "reader", "text": "Как верный и праведный, Богочестивый и непорочный, ты явился освященным, прославляемый всеми истинный угодник Божий, просветил ты мир терпением своим, терпеливейший и доблестный. Потому мы все, Богомудрый, воспеваем твою память."},
  {"id": "ru-mol-0010", "section": "service", "who": "rubric", "text": "Стихира, глас 6-й:"},
  {"id": "ru-mol-0011", "section": "service", "who": "rubric", "text": "Дал еси нам образ терпения и мужества,/ Преблагий Господи,/ угодника Твоего Иова,/ во всех приключшихся ему злостраданиих/ ничимже согрешивша пред Тобою, ниже устнама своима,/ и не давша безумия Тебе, Богу нашему./ Того молитвами и нас сотвори/ победители многоразличных искушений/ и спаси души наша, яко Человеколюбец."},
  {"id": "ru-mol-0012", "section": "service", "who": "reader", "text": "Ты даровал нам образ терпения и мужества,/ Преблагой Господь,/ в лице Твоего угодника Иова,/ во всех суровых жизненных обстоятельствах, приключившихся с ним,/ ничем не согрешившего перед Тобой, ни своими устами,/ и не сделавшегося неразумным перед Тобой, Богом нашим./ Его молитвами и нас сделай/ победителями множества различных искушений/ и спаси наши души, как Человеколюбец."},
  {"id": "ru-mol-0013", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "Боже святой, во святых почивающий, Трисвятым возглашением на небе от ангелов воспеваемый, а на земле от людей во святых Своих прославляемый, давший Твоим Святым Духом каждому благодать по мере дарования Христова и ею поставивший в Церкви Твоей Святой иных апостолами, иных пророками, иных благовестниками, иных пастырями и учителями, по чьим словам проповеди, так как Ты Сам действуешь во всех, наполнилось человечество множеством святых, различными добродетелями благоугодивших Тебе и оставивших нам пример добрых подвигов ради Тебя, в вечное блаженство перешедших и готовых помогать нам в борьбе с напастями, которыми сами искушаемы были."},
  {"id": "ru-mol-0015", "section": "service", "who": "reader", "text": "Этих святых всех и святого праведного Иова вспоминая, и их богоугодное славя житие, Тебя Самого, через них действовавшего, восхваляю и, веруя, что их добродетели – Твои дарования, прилежно молю Тебя, Святой святых, дай мне, грешному, последовать их учению, жизни, любви, вере, долготерпению, и их молитвенной помощью, наиболее же Твоей вседеятельной благодатью, удостоиться с ними небесной славы и восславить пресвятое имя Твое, Отца и Сына, и Святого Духа вовеки. Аминь."},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "От разных недугов и болезней"},
  {"id": "ru-mol-0017", "section": "service", "who": "rubric", "text": "^ Священномученику Ермолаю, наставнику Пантелеимона, иерею Никомидийскому"},
  {"id": "ru-mol-0018", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:2"},
  {"id": "ru-mol-0019", "section": "service", "who": "rubric", "text": "Миром благодати помазан,/ преблаженне отче Ермолае,/ иерей Бога Вышняго явился еси/ и благочестия светлый проповедник,/ мученик же твердый и безмездный врач притекающих к тебе./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "ru-mol-0020", "section": "service", "who": "reader", "text": "Миром благодати помазанный, преблаженный отче Ермолай, священником Бога Всевышнего ты стал и светлым проповедником благочестия, твердым мучеником и безвозмездным врачом для обращающихся к тебе. Слава Давшему тебе силу, слава Венчавшему тебя, слава Подающему через тебя всем исцеления."},
  {"id": "ru-mol-0021", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "ru-mol-0022", "section": "service", "who": "rubric", "text": "Яко святитель благочестно пожив/ и священномучения венец приял еси./ Идольския жертвы погасив,/ добрый пастырь Христова стада был еси, премудре,/ и Пантелеимону истинный учитель./ Сего ради почитаем тя песньми, вопиюще:// от бед избави нас присно молитвами твоими, Ермолае, отче наш."},
  {"id": "ru-mol-0023", "section": "service", "who": "reader", "text": "В сане святительском благоговейно послужив, ты получил венец священномученичества. Идольские жертвы упразднив, ты был добрым пастырем стада Христова, премудрый, и истинным учителем Пантелеимона. Потому почитаем тебя молитвенными песнопениями, взывая: «Всегда избавляй нас от бед молитвами твоими, Ермолай, отче наш»."},
  {"id": "ru-mol-0024", "section": "service", "who": "rubric", "text": "Стихира, глас 6-й:"},
  {"id": "ru-mol-0025", "section": "service", "who": "rubric", "text": "Веселися, граде Никомидие,/ радуйся, соборе верных,/ светло торжествующе в памяти Ермолая священномученика,/ скорбящих сострадательнаго утешителя,/ обидимых теплаго заступника,/ болящих безмезднаго врача,/ молящагося о спасении душ наших."},
  {"id": "ru-mol-0026", "section": "service", "who": "reader", "text": "Веселись, город Никомидия,/ радуйся, собор верных,/ радостно торжествуя в день памяти Ермолая священномученика,/ скорбящих сострадательного утешителя,/ обиженных усердного заступника,/ болящих безвозмездного врача,/ молящегося о спасении душ наших."},
  {"id": "ru-mol-0027", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0028", "section": "service", "who": "rubric", "text": "О преславный священномучениче Ермолае и скорый помощниче христианом в болезнех! Верую от всея души и помышления, яко дадеся тебе от Господа дар болящия врачевати и расслабленныя укрепляти."},
  {"id": "ru-mol-0029", "section": "service", "who": "reader", "text": "О преславный священномученик Ермолай и скорый помощник христианам в болезнях! Я верую от всей души и помышления, что тебе дан дар от Господа болеющих врачевать и расслабленных укреплять."},
  {"id": "ru-mol-0030", "section": "service", "who": "reader", "text": "Поэтому к тебе, как к благодатному врачу болезней, я немощный (немощная) прибегаю и, твой досточтимый образ с благоговением целуя, молюсь: твоим предстательством у Небесного Царя испроси мне болеющему (болеющей) исцеление от удручающих меня болезней, хотя и не достоин (не достойна) тебя, самого благостного отца и постоянного моего заступника, но ты, будучи подражателем Божьего человеколюбия, сделай меня достойным (достойной) твоего заступничества через моё обращение от злых дел к благой жизни, уврачуй обильно дарованной тебе благодатью язвы и раны души и тела моего, даруй мне здоровье и спасение и во всём доброе содействие, и так, тихую и безмятежную жизнь проведу во всяком благочестии и чистоте, сподоблюсь со всеми святыми славить Всесвятое имя Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "^ Преподобному Сампсону странноприимцу"},
  {"id": "ru-mol-0032", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:3"},
  {"id": "ru-mol-0033", "section": "service", "who": "rubric", "text": "В терпении твоем стяжал еси мзду твою, отче преподобне,/ в молитвах непрестанно терпевый,/ нищия возлюбивый и сия удовливый,/ но молися Христу Богу, Сампсоне милостиве блаженне,// спастися душам нашим."},
  {"id": "ru-mol-0034", "section": "service", "who": "reader", "text": "В терпении твоем обрел ты награду свою, отче преподобный, в молитвах постоянно пребывавший, нищих возлюбивший и им помогавший, молись Христу Богу, Сампсон милостивый блаженный о спасении душ наших."},
  {"id": "ru-mol-0035", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0036", "section": "service", "who": "rubric", "text": "Яко врача всеизрядна и молитвенника благоприятна,/ к раце твоей Божественней притекающе, Сампсоне Богомудре преподобне,/ сошедшеся любовию, псалмы и песньми радующеся, Христа прославляем,// таковую тебе благодать подавающа исцелений."},
  {"id": "ru-mol-0037", "section": "service", "who": "reader", "text": "Как к врачу превосходному и молитвеннику помогающему, к раке твоей священной приходя, Сампсон Богомудрый преподобный, собравшись с любовью, в псалмах и песнях духовных, радуясь, Христа прославляем, подающего тебе такую благодать исцелений."},
  {"id": "ru-mol-0038", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0039", "section": "service", "who": "rubric", "text": "О, теплый молитвинниче, благостный отче, преподобне Сампсоне! Моли Бога о мне, грешнем, и низпосли от Всеблагаго Владыки помощь ми и избавление, привременна бо есть жизнь моя и исполнена труда, скорбей и болезней."},
  {"id": "ru-mol-0040", "section": "service", "who": "reader", "text": "О усердный молитвенник, благостный отче, преподобный Сампсон! Моли Бога о мне, грешном (грешной), и ниспошли от Всеблагого Владыки помощь мне и избавление, ибо моя жизнь временна и полна труда, скорбей и болезней."},
  {"id": "ru-mol-0041", "section": "service", "who": "reader", "text": "Укрепи моё сердце, да смогу понести бремя мое, и не допусти, чтобы многие искушения превозмогли мои малые силы, но содействуй мне твоим заступничеством и между невзгодами и бедами направь мой путь в Царство Небесное, да славлю Господа, Который прославился в тебе вовеки. Аминь."},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "^ Молитва Архистратигу Михаилу"},
  {"id": "ru-mol-0043", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:4"},
  {"id": "ru-mol-0044", "section": "service", "who": "rubric", "text": "Небесных воинств Архистратиже,/ молим тя присно мы недостойнии,/ да твоими молитвами оградиши нас/ кровом крил невещественныя твоея славы,/ сохраняя нас, припадающих прилежно и вопиющих:/ от бед избави нас,// яко чиноначальник вышних Сил."},
  {"id": "ru-mol-0045", "section": "service", "who": "reader", "text": "Небесных воинств Архистратиг, непрестанно молим тебя мы, недостойные, чтобы ты оградил нас твоими молитвами под кровом крыл невещественной твоей славы сохраняя нас, припадающих усердно и взывающих: «От бед избавь нас, как начальник Вышних Сил!»"},
  {"id": "ru-mol-0046", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:5"},
  {"id": "ru-mol-0047", "section": "service", "who": "rubric", "text": "Архистратизи Божии,/ служителие Божественныя славы,/ Ангелов начальницы, и человеков наставницы,/ полезное нам просите, и велию милость,// яко Безплотных Архистратизи."},
  {"id": "ru-mol-0048", "section": "service", "who": "reader", "text": "Архистратиги Божии, служители Божественной славы, Ангелов начальники и людей наставники, полезное нам испросите и великую милость, как бесплотных Архистратиги."},
  {"id": "ru-mol-0049", "section": "service", "who": "rubric", "text": "^ Молитва Архангелу Рафаилу"},
  {"id": "ru-mol-0050", "section": "service", "who": "rubric", "text": "О святый великий Архангеле Рафаиле, престолу Божию предстояй! Ты благодатию, от всемогущаго Врача душ и телес наших тебе данною, праведнаго мужа Товита от слепоты телесныя исцелил еси, и сына его Товию, спутешествуя ему, от злаго духа сохранил еси."},
  {"id": "ru-mol-0051", "section": "service", "who": "reader", "text": "О святой великий Архангел Рафаил, предстоящий Божьему Престолу! Ты благодатью, данной тебе от всемогущего Врача душ и тел наших, праведного мужа Товита от слепоты исцелил (Тов. 3:16-17), и сына его Товию, путешествуя с ним, сохранил от злого духа."},
  {"id": "ru-mol-0052", "section": "service", "who": "reader", "text": "Со всем усердием молю тебя, будь мне путеводителем в моей жизни, сохрани от всех видимых и невидимых врагов, исцели душевные и телесные мои болезни, направь мою жизнь к покаянию в грехах и к совершению добрых дел."},
  {"id": "ru-mol-0053", "section": "service", "who": "reader", "text": "О святой великий Архангел Рафаил! Услышь меня, грешного, молящегося (грешную, молящуюся) тебе и сподоби в этой и будущей жизни благодарить и славить общего Создателя нашего в бесконечные веки веков. Аминь."},
  {"id": "ru-mol-0054", "section": "service", "who": "rubric", "text": "^ Мученику Трифону"},
  {"id": "ru-mol-0055", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:6"},
  {"id": "ru-mol-0056", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Трифон,/ во страдании своем венец прият нетленный от Тебе, Бога нашего:/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "ru-mol-0057", "section": "service", "who": "reader", "text": "Мученик Твой, Господи, Трифон подвигом своим венец нетленный получил от Тебя, Бога нашего; ибо он, имея силу Твою, мучителей низложил, сокрушил и демонов немощные дерзости. По молитвам его, Христе Боже, спаси души наши."},
  {"id": "ru-mol-0058", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "Троическою твердостию/ многобожие разрушил еси от конец, всеславне,/ честен во Христе быв, и, победив мучители во Христе Спасителе,/ венец приял еси мученичества твоего/ и дарования Божественных исцелений,// яко непобедимь."},
  {"id": "ru-mol-0060", "section": "service", "who": "reader", "text": "Силою Троицы разрушил ты многобожие в пределах земных, преславный, досточтимым пред Господом став; и, победив мучителей Христом Спасителем, получил венец мученичества твоего и дарования Божественных исцелений, как непобедимый."},
  {"id": "ru-mol-0061", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0062", "section": "service", "who": "rubric", "text": "О святый мучениче Христов Трифоне, скорый помощниче и всем к тебе прибегающим и молящимся пред святым твоим образом скоропослушный предстателю!"},
  {"id": "ru-mol-0063", "section": "service", "who": "reader", "text": "О святой мученик Христов Трифон, скорый помощник и всем к тебе прибегающим и молящимся пред святым твоим образом скоро слышащий их заступник."},
  {"id": "ru-mol-0064", "section": "service", "who": "reader", "text": "Услышь ныне и на всякий час моление нас, недостойных рабов твоих, почитающих святую память твою во всесвященном этом храме, и ходатайствуй о нас пред Господом на каждом месте."},
  {"id": "ru-mol-0065", "section": "service", "who": "reader", "text": "Ты, о угодник Христов, великими чудесами просиявший, источаешь исцеления прибегающим к тебе с верой и находящихся в скорбях людей защищаешь, как сам ты обещал прежде исхода твоего из этой тленной жизни молиться за нас ко Господу и испросил у Него такой дар: если кто в какой-либо нужде, печали и болезни душевной или телесной призывать начнет святое имя твоё, тот да избавлен будет от всякого нападения злого."},
  {"id": "ru-mol-0066", "section": "service", "who": "reader", "text": "И как ты некогда царскую дочь в Риме мучимую диаволом исцелил, так и нас от лютых его козней сохрани во все дни нашей жизни, особенно же в день последнего нашего вздоха ходатайствуй о нас."},
  {"id": "ru-mol-0067", "section": "service", "who": "reader", "text": "Будь нам тогда помощником и скоро прогони лукавых духов, и в Царство Небесное приведи. И там, где ты ныне предстоишь с сонмами святых у Престола Божьего, моли Господа, да сподобит и нас стать причастниками вечного веселия и радости, дабы мы с тобою вместе прославляли Отца, и Сына, и Святого Утешителя Духа во веки. Аминь."},
  {"id": "ru-mol-0068", "section": "service", "who": "rubric", "text": "^ Преподобному Иову Почаевскому"},
  {"id": "ru-mol-0069", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "ru-mol-0070", "section": "service", "who": "reader", "text": "Возложив на себя иго Христово с юности (Мф.11:29-30), преподобный отче Иов, многие годы ты свято подвизался на поприще благочестия в Угорницкой обители и на острове Дубенском и, прийдя к горе Почаевской, ознаменовавшейся исцеляющей стопой Пресвятой Богородицы, в тесной пещере каменной, ради богомыслия и молитвы ты многократно закрывался и, благодатью Божией укрепляясь, мужественно потрудился ты на пользу Церкви Христовой и обители твоей, а также против врагов Православия и благочестия христианского и, обучая тому же ряды монашествующих, ты привел их как победителей Владыке и Богу. Его моли о спасении наших душ."},
  {"id": "ru-mol-0071", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0072", "section": "service", "who": "rubric", "text": "Возсия от спуда земнаго сокровище нетленное мощей твоих,/ угодниче Божий,/ яко, благочестно пожив в вере Христа Бога нашего,/ достигл еси добродетелей совершенства,/ и, оставль сладость жития преходящаго,/ в пещере горы Почаевския в пощениих, молитвах и трудех свято подвизался еси,/ и теми тело твое увядил еси./ Ныне же, прешед к Богу в безмятежный и вечный покой,/ молишися о всех с верою к тебе прибегающих./ Радуйся, Иове, преславный угодниче Божий// и обители Почаевския украшение."},
  {"id": "ru-mol-0073", "section": "service", "who": "reader", "text": "Воссияло скрытое под землей нетленное сокровище твоих мощей, угодник Божий, так как ты благочестиво жил с верой во Христа Бога нашего, достиг совершенства добродетелей и, оставив наслаждения временной жизни, в пещере Почаевской горы в посте, молитвах и трудах свято подвизался и этим тело твое иссушил. Сейчас же, перейдя к Богу в безмятежный и вечный покой, ты молишься обо всех с верой к тебе приходящих. Радуйся, Иов, прославляемый угодник Божий и украшение Почаевской обители."},
  {"id": "ru-mol-0074", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0075", "section": "service", "who": "reader", "text": "О всесвятой и преславный угодник Божий, преподобный отче наш Иове, постоянный о нас ко Господу молитвенник и усердный предстатель о душах наших, к тебе со всем смирением ныне прибегаем и, поминая подвиги и чудеса твои, которые ты сотворил и творишь на земле, мы просим и молим твою благость: потому что ты сильно и неизменно трудился в вере Христа Бога нашего, и её до конца в себе и во всех твоих близких целой и невредимой сохранив от всяких искушений и пагубных ересей, так и нас укрепи в Православии и единомыслии, отгоняя молитвами твоими всякую тьму неверия и неправомыслия от сердец и помышлений наших."},
  {"id": "ru-mol-0076", "section": "service", "who": "reader", "text": "Послуживший Господу и Богу твоему благими делами и несказанным самоотвержением в трудах, бдении и пощении, наставь нас на путь всякой добродетели и благости, избавляя от искушений и грехов, которые удаляют нас от Бога и повергают в бездну зла всю нашу жизнь."},
  {"id": "ru-mol-0077", "section": "service", "who": "reader", "text": "Явившись некогда с Пречистой Девой Богородицей на верху Почаевской горы для спасения твоей обители от нашествия и осады мусульман, и ныне поспеши на помощь нашей стране против всех врагов наших, внешних и внутренних, утверждая мир и тишину в нашей земле, да безмятежную жизнь проведём во всяком благочестии и чистоте."},
  {"id": "ru-mol-0078", "section": "service", "who": "reader", "text": "И всем к тебе прибегающим и припадающим к раке честных и многоцелебных твоих мощей и твоей помощи и заступничества требующим неоскудевающии милости щедро подавай, не оставь и нас, осиротевших и беспомощных, тебе молящихся, избавляя от каждой скорби, гнева и насилия, от голода, мора, землетрясения, наводнения, огня, меча, нашествия иноплеменников и междоусобной войны."},
  {"id": "ru-mol-0079", "section": "service", "who": "reader", "text": "О Божий угодник, обрати милостивое своё внимание от Престола Царя Славы, у Которого ты ныне предстоишь со Архангелами и Ангелами и со всеми святыми, на твою Почаевскую обитель, ей ты прежде мудро управлял, создав её всехвальной и дивной твоей жизнью, и сохрани её твоими молитвами и каждый город, и страну и всех отовсюду, на море и на суше, в пустынях и в многоразличных заключениях тебя призывающих, от всякого зла, видимого и невидимого, да так, с твоей помощью и ходатайством спасаемые, в этом веке и по окончании нашей жизни сподобимся вместе с тобой славить и воспевать всечестное имя Отца, и Сына, и Святого Духа во веки веков. Аминь."},
  {"id": "ru-mol-0080", "section": "service", "who": "rubric", "text": "^ Святому и праведному Иоанну Кронштадтскому"},
  {"id": "ru-mol-0081", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:7"},
  {"id": "ru-mol-0082", "section": "service", "who": "rubric", "text": "Православныя веры поборниче,/ земли Российския печальниче,/ пастырем правило и образе верным,/ покаяния и жизни во Христе проповедниче,/ Божественных Таин благоговейный служителю/ и дерзновенный о людех молитвенниче,/ отче праведный Иоанне,/ целителю и предивный чудотворче,/ граду Кронштадту похвало/ и Церкви нашея украшение,/ моли всеблагаго Бога// умирити мир и спасти души наша."},
  {"id": "ru-mol-0083", "section": "service", "who": "reader", "text": "Православной веры поборник, земли Российской попечитель, пастырям правило и пример верующим, покаяния и жизни во Христе проповедник, Божественных Тайн благоговейный служитель и дерзновенный молитвенник о людях, отче праведный Иоанн, целитель и удивительный чудотворец, городу Кронштадту слава и Церкви нашей украшение, моли всеблагого Бога мир умиротворить и спасти души наши."},
  {"id": "ru-mol-0084", "section": "service", "who": "rubric", "text": "Кондак, глас 3-й:"},
  {"id": "ru-mol-0085", "section": "service", "who": "rubric", "text": "Днесь пастырь Кронштадтский/ предстоит Престолу Божию/ и усердно молит о верных/ Христа Пастыреначальника,/ обетование давшаго:/ созижду Церковь Мою/ и врата адова// не одолеют ей."},
  {"id": "ru-mol-0086", "section": "service", "who": "reader", "text": "Сегодня пастырь Кронштадский предстоит Престолу Божию и усердно молит о верующих во Христа Пастыреначальника, давшего обещание: «Создам Церковь Мою и врата ада не одолеют ее» (Мф.16:18)."},
  {"id": "ru-mol-0087", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0088", "section": "service", "who": "rubric", "text": "О великий угодниче Христов, святый праведный отче Иоанне Кронштадтский, пастырю дивный, скорый помощниче и милостивый предстателю!"},
  {"id": "ru-mol-0089", "section": "service", "who": "reader", "text": "О великий угодник Христов, святой праведный отец Иоанн Кронштадтский, пастырь дивный, скорый помощник и милосердный предстатель!"},
  {"id": "ru-mol-0090", "section": "service", "who": "reader", "text": "Вознося славословие Триединому Богу, ты молитвенно взывал: «Имя Тебе — Любовь: не отвергни меня, заблуждающегося. Имя Тебе — Сила: укрепи меня, изнемогающего и падающего. Имя Тебе — Свет: просвети душу мою, омраченную житейскими страстями. Имя Тебе — Мир: умири мятущуюся душу мою»."},
  {"id": "ru-mol-0091", "section": "service", "who": "reader", "text": "Ныне благодарная твоему предстательству всероссийская паства молится тебе: носящий имя Христа и праведный угодник Божий! Любовью твоей озари нас, грешных и немощных, сподоби нас принести достойные плоды покаяния и неосужденно причащаться Христовых Тайн."},
  {"id": "ru-mol-0092", "section": "service", "who": "reader", "text": "Силою твоей веру в нас укрепи, в молитве поддержи, недуги и болезни исцели, от напастей, врагов видимых и невидимых, избавь. Светом лица твоего служителей и предстателей алтаря Христова на святые подвиги пастырского служения подвигни, младенцем воспитание даруй, юных наставь, старость поддержи, святыни храмов и святые обители озари!"},
  {"id": "ru-mol-0093", "section": "service", "who": "reader", "text": "Умири, чудотворец и прозорливец превосходнейший, народы страны нашей, благодатью и даром Святого Духа избавь от междоусобных войн, собери рассеянных, обрати прельщённых и присоедини к Святой Соборной и Апостольской Церкви."},
  {"id": "ru-mol-0094", "section": "service", "who": "reader", "text": "Твоей милостью браки в мире и единомыслии сохрани, монашествующим в делах благих преуспеяние и благословение даруй, малодушных утешь, страдающих от духов нечистых освободи, пребывающих в нужде и бедствии помилуй и нас на путь спасения наставь."},
  {"id": "ru-mol-0095", "section": "service", "who": "reader", "text": "Во Христе живущий, отец наш Иоанн, приведи нас к Невечернему Свету жизни вечной, да удостоимся вместе с тобой вечного блаженства, восхваляя и превознося Бога во веки веков. Аминь"},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "^ Святителю Спиридону чудотворцу, епископу Тримифунтскому"},
  {"id": "ru-mol-0097", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:8"},
  {"id": "ru-mol-0098", "section": "service", "who": "rubric", "text": "Собора Перваго показался еси поборник и чудотворец,/ Богоносе Спиридоне, отче наш./ Темже мертву ты во гробе возгласив,/ и змию в злато претворил еси,/ и внегда пети тебе святыя молитвы/ Ангелы, сослужащия тебе, имел еси, священнейший./ Слава Давшему тебе крепость,/ слава Венчавшему тя,// слава Действующему тобою всем исцеления."},
  {"id": "ru-mol-0099", "section": "service", "who": "reader", "text": "На соборе первом защитником истины и чудотворцем явился ты, Богоносный Спиридон, отче наш. Потому ты к мертвой в могиле обратился, и змею в золото превратил, и при пении святых молитв Ангелы сослужили тебе, священнейший! Слава Прославившему тебя, слава Увенчавшему тебя, слава Совершающему чрез тебя всем исцеления!"},
  {"id": "ru-mol-0100", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "Любовию Христовою уязвився, священнейший,/ ум вперив зарею Духа,/ детельным видением твоим деяние обрел еси, Богоприятне,/ жертвенник Божественный быв,// прося всем Божественнаго сияния."},
  {"id": "ru-mol-0102", "section": "service", "who": "reader", "text": "Любовью Христовой уязвившись, священнейший, ум окрылив сиянием Духа, ты, Боговдохновенный, преуспел в действенном созерцании, став жертвенником Божественным, прося для всех Божественного озарения."},
  {"id": "ru-mol-0103", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "О великий и пречудный святителю Христов и чудотворче Спиридоне, Керкирская похвало, всея вселенныя светильниче пресветлый, теплый к Богу молитвенниче и всем к тебе прибегающим и с верою молящимся скоропредстательный заступниче!"},
  {"id": "ru-mol-0105", "section": "service", "who": "reader", "text": "О великий и пречудный святитель Христов и чудотворец Спиридон, Керкиры похвала, всей вселенной светильник пресветлый, горячий к Богу молитвенник и всем, к тебе прибегающим и с верою молящимся, скоро приходящий на помощь заступник!"},
  {"id": "ru-mol-0106", "section": "service", "who": "reader", "text": "Ты веру православную на Никейском Соборе посреди отцов преславно изъяснил, ты единство Святой Троицы чудесною силою показал и еретиков до конца посрамил. Услышь нас, грешных, святитель Христов, молящихся тебе, и сильным твоим предстательством пред Господом избавь нас от всякого тяжкого несчастья: от голода, потопа, огня и смертоносной язвы."},
  {"id": "ru-mol-0107", "section": "service", "who": "reader", "text": "Ты во временной жизни своей от всех этих бедствий избавлял людей твоих: от нашествия мусульман и от голода страну твою сохранил, царя от неизлечимого недуга избавил и многих грешников к покаянию привел, мертвых преславно воскрешал, за святость жития твоего Ангелов невидимо в церкви поющих сослужителями своими имел. Так прославил тебя, верного Своего раба, Владыка Христос, ибо все тайные человеческие деяния даровал Он тебе прозревать и обличать неправедно живущих."},
  {"id": "ru-mol-0108", "section": "service", "who": "reader", "text": "Многим, в скудости и нужде живущим ты усердно помогал, людей бедных во время голода изобильно напитал и иные многие знамения силою в тебе живущего Духа Божия сотворил."},
  {"id": "ru-mol-0109", "section": "service", "who": "reader", "text": "Так и нас не оставь, святитель Христов, поминай нас, чад своих, у Престола Вседержителя и умоли Господа, да подаст многих наших грехов прощение, безбедную и мирную жизнь да дарует нам, кончину же жизни непостыдную и мирную и блаженства вечного в будущем веке сподобит нас, дабы мы непрестанно воссылали славу и благодарение Отцу, и Сыну, и Духу Святому, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "^ Святому великомученику и целителю Пантелеимону"},
  {"id": "ru-mol-0111", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:9"},
  {"id": "ru-mol-0112", "section": "service", "who": "rubric", "text": "Страстотерпче святый и целебниче Пантелеимоне,/ моли Милостиваго Бога,/ да прегрешений оставление// подаст душам нашим."},
  {"id": "ru-mol-0113", "section": "service", "who": "reader", "text": "Страстотерпец святой и целитель Пантелеимон, умоли милостивого Бога, да согрешений прощение подаст Он душам нашим."},
  {"id": "ru-mol-0114", "section": "service", "who": "rubric", "text": "Кондак, глас 5-й:"},
  {"id": "ru-mol-0115", "section": "service", "who": "rubric", "text": "Подражатель сый Милостиваго/, и исцелений благодать от Него прием,/ страстотерпче и мучениче Христа Бога,/ молитвами твоими душевныя наша недуги исцели,/ отгоня присно борца соблазны от вопиющих верно:// спаси ны, Господи."},
  {"id": "ru-mol-0116", "section": "service", "who": "reader", "text": "Подражатель Милостивого и получивший от Него исцелений благодать, страстотерпец и мученик Христа Бога! Молитвами твоими душевные наши недуги исцели, отгоняя всегда вражии соблазны от взывающих непрестанно: «Спаси нас, Господи!»"},
  {"id": "ru-mol-0117", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0118", "section": "service", "who": "rubric", "text": "Святый великомучениче и целителю Пантелеимоне, Бога милостиваго подражателю!"},
  {"id": "ru-mol-0119", "section": "service", "who": "reader", "text": "Святой великомученик и целитель Пантелеймон, Бога милостивого последователь!"},
  {"id": "ru-mol-0120", "section": "service", "who": "reader", "text": "Обрати внимание благим своим сердцем и услышь нас, грешных, перед святым твоим образом усердно молящихся."},
  {"id": "ru-mol-0121", "section": "service", "who": "reader", "text": "Испроси нам у Господа Бога, Которому ты с Ангелами предстоишь на Небесах, оставление грехов и прегрешении наших."},
  {"id": "ru-mol-0122", "section": "service", "who": "reader", "text": "Исцели болезни душевные и телесные рабов Божьих, сейчас поминаемых, здесь стоящих и всех христиан православных, к твоей защите приходящих."},
  {"id": "ru-mol-0123", "section": "service", "who": "reader", "text": "Вот мы, по грехам своим люто одержимы во многих недугах своих и не имеем помощи и утешений, к тебе прибегаем, потому что тебе дана благодать молиться за нас и исцелять каждый недуг и каждую болезнь."},
  {"id": "ru-mol-0124", "section": "service", "who": "reader", "text": "Подари всем нам святыми молитвами твоими здоровье и сил души и тела, утверждение веры и благочестия и всё для временной жизни и для спасения необходимое."},
  {"id": "ru-mol-0125", "section": "service", "who": "reader", "text": "Ибо, удостоившись тобою больших и богатых милостей, славим тебя и подателя всех благ, дивного во всех святых, Бога нашего, Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0126", "section": "service", "who": "rubric", "text": "^ Святому великомученику и целителю Пантелеимону молитва 2-я, наедине от лица болящего читаемая"},
  {"id": "ru-mol-0127", "section": "service", "who": "rubric", "text": "О великий угодниче Христов, страстотерпче и врачу многомилостивый, Пантелеимоне!"},
  {"id": "ru-mol-0128", "section": "service", "who": "reader", "text": "О великий угодник Христов, страстотерпец и врач многомилостивый, Пантелеимон!"},
  {"id": "ru-mol-0129", "section": "service", "who": "reader", "text": "Умилосердись надо мной, грешным рабом (грешной рабой), услышь боль и вопль мой, умилостиви Небесного верховного Врача душ и тел наших, Христа Бога нашего, да подарит мне исцеление от гнетущего меня недуга."},
  {"id": "ru-mol-0130", "section": "service", "who": "reader", "text": "Прими недостойное моление грешнейшего (грешнейшей) более всех людей."},
  {"id": "ru-mol-0131", "section": "service", "who": "reader", "text": "Посети меня благодатным посещением. Не отврати твоё лицо от греховных язв моих, помажь елеем милости твоей и исцели меня: да буду здоровым (здоровой) душой и телом, остаток дней моих, благодатью Божьей, буду проводить в покаянии и угождении Богу и сподоблюсь принять благой конец жизни моей на земле."},
  {"id": "ru-mol-0132", "section": "service", "who": "reader", "text": "О угодник Божий! Умоли Христа Бога, твоим представительством да дарует здоровье моему телу и спасение души моей. Аминь."},
  {"id": "ru-mol-0133", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Всех скорбящих радость»"},
  {"id": "ru-mol-0134", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:"},
  {"id": "ru-mol-0135", "section": "service", "who": "rubric", "text": "Всех скорбящих Радосте,/ и обидимых Заступнице,/ и алчущих Питательнице,/ странных Утешение,/ обуреваемых Пристанище,/ больных посещение,/ немощных покров и заступнице,/ Жезл старости,/ Мати Бога Вышняго Ты еси, Пречистая: // потщися, молимся, спастися рабом Твоим."},
  {"id": "ru-mol-0136", "section": "service", "who": "reader", "text": "Всех скорбящих Радость, / и обижаемых Заступница, / и алчущих Питательница, / странников Утешение, / обуреваемых Пристанище, / больных посещение, / немощных покров и Заступница, / Жезл старости, / Матерь Бога Всевышнего – Ты, Пречистая; // поспеши, молимся, для спасения рабов Твоих."},
  {"id": "ru-mol-0137", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:10"},
  {"id": "ru-mol-0138", "section": "service", "who": "rubric", "text": "Не имамы иныя помощи,/ не имамы иныя надежды,/ разве Тебе, Владычице./ Ты нам помози:/ на Тебе надеемся и Тобою хвалимся,/ Твои бо есмы раби,// да не постыдимся."},
  {"id": "ru-mol-0139", "section": "service", "who": "reader", "text": "Не имеем иной помощи, не имеем иной надежды, кроме Тебя, Владычица. Ты нам помоги: на Тебя надеемся и Тобою хвалимся, ибо мы – Твои рабы; да не постыдимся!"},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0141", "section": "service", "who": "rubric", "text": "О Пресвятая Владычице Богородице, Преблагословенная Мати Христа Бога Спасителя нашего, всех скорбящих Радосте, больных посещение, немощных покрове и заступнице, вдовиц и сирых покровительнице, матерей печальных всенадежная утешительнице, младенцев немощных крепосте, и всем безпомощным всегда готовая помоще и верное прибежище!"},
  {"id": "ru-mol-0142", "section": "service", "who": "reader", "text": "О Пресвятая Владычица Богородица, Преблагословенная Матерь Христа Бога Спасителя нашего, всех скорбящих Радость, больных посещение, немощных покров и заступница, вдов и сирот покровительница, матерей, пребывающие в печали, самая надежная утешительница, немощных младенцев сила, и всегда готовая помочь всем, лишенным помощи, и истинное прибежище!"},
  {"id": "ru-mol-0143", "section": "service", "who": "reader", "text": "Тебе, о Всемилостивая, дана от Всевышнего благодать заступаться за всех и избавлять от скорбей и болезней, ведь Ты сама претерпела лютую скорбь и боль, когда смотрела на добровольное страдание Своего возлюбленного Сына, видела, как Его распинают на Кресте, тогда, как предсказал Симеон, Твоё сердце пронзило оружие."},
  {"id": "ru-mol-0144", "section": "service", "who": "reader", "text": "Поэтому, о Матерь, любящая своих детей, услышь голос нашего моления, утешь нас, скорбящих, потому что ты верная радости Ходатаица: предстоя перед престолом Пресвятой Троицы по правую руку Своего Сына, Христа нашего Бога, Ты можешь, если захочешь, испросить нам всё, что нам полезно."},
  {"id": "ru-mol-0145", "section": "service", "who": "reader", "text": "Поэтому с верой в сердце и любовью от души мы обращаемся к Тебе как к Царице и Владычице и с дерзновением взываем к Тебе, как написано во псалме: «Услышь, Дочь, и посмотри, и склони ухо Своё» (ср.: Пс. 44:11), услышь наше моление, и избавь от окружающих бед и скорбей; ведь Ты прошения всех верных, как скорбящих радость, исполняешь и душам их даёшь мир и утешение."},
  {"id": "ru-mol-0146", "section": "service", "who": "reader", "text": "Ты видишь, в какой мы беде и скорби: прояви милость Свою к нам, пошли утешение уязвленному печалью нашему сердцу, покажи и прославь на нас грешных богатство Твоего милосердия, подай нам слёзы покаяния для очищения наших грехов и утоления Божьего гнева, да с чистым сердцем, благой совестью и искренней надеждой прибегаем к Твоему ходатайству и заступничеству: прими, всемилостивая Владычица наша Богородица, наше усердное моление, обращённое к Тебе, и не прогони нас, не достойных Твоей доброты, но подай нам избавление от скорби и болезни, защити нас от всех нападений врага и от клеветы людей, будь помощницей во все дни нашей жизни неотступной, чтобы мы всегда под Твоим материнским Покровом оставались целыми и невредимыми благодаря Твоему заступничеству и молитвам к Сыну Твоему и Богу Спасителю нашему, Кому подобает вся слава, честь и поклонение, вместе с Его не имеющим начала Отцом и Святым Духом, сейчас, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0147", "section": "service", "who": "rubric", "text": "^ Бессребреникам и чудотворцам Косме и Дамиану"},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "Тропарь, глас 5-й:11"},
  {"id": "ru-mol-0149", "section": "service", "who": "rubric", "text": "Святии безсребреницы и чудотворцы Косьмо и Дамиане,/ посетите немощи наша:// туне приясте, туне дадите нам."},
  {"id": "ru-mol-0150", "section": "service", "who": "reader", "text": "Святые бессребренники и чудотворцы Косма и Дамиан, посетите немощи наши; даром вы получили благодать, даром подайте и нам."},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0152", "section": "service", "who": "rubric", "text": "Благодать приимше исцелений,/ простираете здравие сущим в нуждах, врачеве,/ чудотворцы преславнии,/ но вашим посещением ратников дерзости низложите,// мир исцеляюще чудесы."},
  {"id": "ru-mol-0153", "section": "service", "who": "reader", "text": "Получив благодать исцелений, простираете вы здравие пребывающим в бедах, врачи, чудотворцы славные; но вашим посещением и врагов дерзости низложите, мир исцеляя чудесами."},
  {"id": "ru-mol-0154", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0155", "section": "service", "who": "rubric", "text": "К вам, святии безсребреницы и чудотворцы Космо и Дамиане, яко к скорым помощником и теплым молитвенником о спасении нашем, мы, недостойнии, преклоньше колена, прибегаем и, припадающе, усердно вопием: не презрите моления нас, грешных, немощных, во многая беззакония впадших и по вся дни и часы согрешающих."},
  {"id": "ru-mol-0156", "section": "service", "who": "reader", "text": "К вам, святые бессребреники и чудотворцы Косма и Дамиан, как к быстрым помощникам и усердным молитвенникам о нашем спасении, мы, недостойные, преклонив колена, прибегаем и, припав, с усердием взываем: не пренебрегайте нашими молитвами, грешных, немощных, впавших в многие беззакония и изо дня в день и час согрешающих."},
  {"id": "ru-mol-0157", "section": "service", "who": "reader", "text": "Умолите Господа, да продлит нам, недостойным рабам Своим, великие и богатые Свои милости; избавьте нас от каждой скорби и болезни, потому что вы приняли от Господа и Спаса нашего Иисуса Христа обильную благодать исцелений за крепкую веру, безвозмездное врачевание и мученическую кончину вашу."},
  {"id": "ru-mol-0158", "section": "service", "who": "reader", "text": "Услышьте нас, молящихся, и благоприятным ходатайством вашим испросите у Христа Бога православным людям победу над врагами и одоление их. Снова, припав, прилежно молим: испросите нам у Господа всё благополезное для нашей временной жизни, но особенно служащее для спасения в вечности, да сподобимся вашими молитвами получить кончину христианскую, безболезненную, непостыдную, мирную, и да избавимся от козней диавольских и вечных мук, будем же наследниками бесконечного же и блаженного Царства Небесного."},
  {"id": "ru-mol-0159", "section": "service", "who": "reader", "text": "О угодники Божьи, не переставайте молиться за нас, с верою к вам прибегающих. Хотя из-за множества наших грехов и не достойны мы вашего милосердия, но вы, верные подражатели Божьего человеколюбия, сделайте, да мы принесём достойные плоды покаяния и достигнем вечного покоя, хваля и благословляя дивного во святых Своих Господа и Бога и Спаса нашего Иисуса Христа, и Пречистую Его Матерь, и ваше усердное заступничество, всегда, ныне, и вечно, и во веки веков. Аминь."},
  {"id": "ru-mol-0160", "section": "service", "who": "rubric", "text": "^ Пророку, Предтече и Крестителю Господню Иоанну"},
  {"id": "ru-mol-0161", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:12"},
  {"id": "ru-mol-0162", "section": "service", "who": "rubric", "text": "Память праведнаго с похвалами,/ тебе же довлеет свидетельство Господне, Предтече:/ показал бо ся еси воистину и пророков честнейший,/ яко и в струях крестити сподобился еси Проповеданнаго./ Темже за истину пострадав радуяся,/ благовестил еси и сущим во аде Бога явльшагося плотию,/ вземлющаго грех мира,// и подающаго нам велию милость."},
  {"id": "ru-mol-0163", "section": "service", "who": "reader", "text": "Память праведника чтится похвалами, тебе же довольно свидетельства Господня, Предтеча, ведь явился ты поистине из пророков славнейшим, ибо удостоился в струях крестить Проповеданного. Потому за истину пострадав с радостью, благовествовал ты и находящимся во аде Бога, явившегося во плоти, подъемлющего грех мира и подающего нам великую милость."},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "Кондак, глас 5-й:"},
  {"id": "ru-mol-0165", "section": "service", "who": "rubric", "text": "Предтечево славное усекновение,/ смотрение бысть некое Божественное;/ да и сущим во аде Спасово проповесть пришествие./ Да рыдает убо Иродиа,/ беззаконное убийство испросивши:/ не закон бо Божий, ни живый век возлюби,// но притворный, привременный."},
  {"id": "ru-mol-0166", "section": "service", "who": "reader", "text": "Предтечи славное усекновение произошло по некоему Божественному замыслу, чтобы он и пребывавшим во аде возвестил о пришествии Спасителя. Да восплачет же Иродиада, беззаконное убийство испросившая: ведь не закон она Божий возлюбила, не вечную жизнь, но обманчивую и временную."},
  {"id": "ru-mol-0167", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0168", "section": "service", "who": "rubric", "text": "Крестителю Христов, проповедниче покаяния, кающагося не презри мене, но совокупляяся с вои Небесными, молися ко Владыце за мене, недостойнаго, унылаго, немощнаго и печальнаго, во многия беды впадшаго, утружденнаго бурными помыслы ума моего."},
  {"id": "ru-mol-0169", "section": "service", "who": "reader", "text": "Креститель Христов, проповедник покаяния, не презри меня, кающегося (кающуюся), но вместе с Воинствами Небесными молись Владыке за меня, недостойного(-ую), унывающего(-ую), немощного(-ую) и печального(-ую), во многие беды впадшего(-ую), утружденного(-ую) бурными помыслами ума моего."},
  {"id": "ru-mol-0170", "section": "service", "who": "reader", "text": "Я — вертеп злых дел, совсем не полагаю конца своему греховному обычаю, потому что ум мой пригвожден к земным вещам. Что делать? Не знаю. И к кому прибегну, чтобы была спасена моя душа? Только к тебе, святой Иоанн, соименный благодати, я знаю, что ты, после Богородицы, пред Господом больше всех рождённых, потому что ты сподобился коснуться главы Царя Христа, Агнца Божия, берущего грехи мира. Его моли за грешную мою душу, чтобы хотя бы отныне, в одиннадцатый час, я понёс (понесла) благую тягость и получил(-а) награду с последними."},
  {"id": "ru-mol-0171", "section": "service", "who": "reader", "text": "О Креститель Христов, почитаемый Предтеча, последний Пророк, первый по благодати мученик, постников и пустынников наставник, чистоты учитель и ближайший друг Христов! Тебя молю, к тебе прибегаю: не лиши меня твоего заступничества, но подними меня, впавшего в многие грехи. Обнови мою душу покаянием, как вторым крещением, поскольку ты и того и другого начальник: крещением омывая грех прародителей, покаянием очищая каждого от скверных дел. Очисти меня, грехами осквернённого(-ую), и побуди войти, куда ничто скверное не входит, в Царство Небесное. Аминь."},
  {"id": "ru-mol-0172", "section": "service", "who": "rubric", "text": "Грудные болезни"},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "^ Святому Димитрию, митрополиту Ростовскому"},
  {"id": "ru-mol-0174", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:13"},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "Православия ревнителю и раскола искоренителю,/ Российский целебниче, и новый к Богу молитвенниче,/ списаньми твоими буих уцеломудрил еси,/ цевнице духовная, Димитрие блаженне,// моли Христа Бога спастися душам нашим."},
  {"id": "ru-mol-0176", "section": "service", "who": "reader", "text": "Православия ревнитель и раскола искоренитель, Российский целитель и новый к Богу молитвенник, сочинениями твоими неразумных ты вразумил, лира духовная, Димитрий блаженный, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0178", "section": "service", "who": "rubric", "text": "Звезду Российскую от Киева возсиявшую,/ и чрез Новград Северский в Ростов достигшую,/ всю же страну сию ученьми и чудесы озарившую,/ ублажим златословеснаго учителя Димитрия,/ той бо всем вся написа, яже к наставлению,/ да всех приобрящет, якоже Павел Христу,// и спасет правоверием души наша."},
  {"id": "ru-mol-0179", "section": "service", "who": "reader", "text": "Звезду Российскую в Киеве воссиявшую и через Новгород Северский в Ростов дошедшую, всю же страну нашу учениями и чудесами озарившую, прославим красноречивого учителя Димитрия, ибо он для всех написал все к наставлению, чтобы привести всех ко Христу, как Апостол Павел (1Кор.9:22), и спасти Православием души наши."},
  {"id": "ru-mol-0180", "section": "service", "who": "rubric", "text": "Молитва:14"},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "О предивный и преславный чудотворче Димитрие, исцеляяй недуги человеческия! Ты неусыпно молиши Господа Бога нашего о всех грешных: молю убо тя, буди ми ходатай пред Господем и помощник на преоборение страстей ненасытныя плоти моея и на одоление стрел сопротивника моего диавола, имиже уязвляет немощное сердце мое и, аки гладный и лютый зверь, алчет погубити душу мою."},
  {"id": "ru-mol-0182", "section": "service", "who": "reader", "text": "О предивный и преславный чудотворец Димитрий, исцеляющий недуги людей! Ты неутомимо молишь Господа Бога нашего о всех грешных: поэтому молю тебя, будь за меня посредником перед Господом и помощником в победе над страстями ненасытной моей плоти и на одоление стрел моего врага диавола, который уязвляет немощное моё сердце и, словно голодный и лютый зверь, желает поглотить мою душу."},
  {"id": "ru-mol-0183", "section": "service", "who": "reader", "text": "Ты, святитель Христов, моё ограждение, ты мой заступник и оружие! С твоим содействием преодолею всё во мне противящееся воле Царя царствующих. Ты, великий чудотворец, во дни подвигов твоих в этом мире ревнующий о Православной Церкви Божьей, как истинный и добрый пастырь, без соблазна обличал грехи и невежества людей, и уклонившихся от пути правды в ереси и расколы ты наставлял на путь истины. Поэтому содействуй и мне исправить кратковременный путь моей жизни, да беспрепятственно пойду по пути заповедей Божьих и без лени поработаю моему Господу Иисусу Христу, как единому Владыке моему, Искупителю и праведному моему Судии."},
  {"id": "ru-mol-0184", "section": "service", "who": "reader", "text": "К тому же припадая, молюсь к Тебе, угодник Божий, когда покинет душа моя тело моё, избавь её от тёмных мытарств, не имею добрых дел для моего оправдания, не дай сатане возгордиться победой над немощной моей душой. Избави её от геенны, где плач и скрежет зубов, и святыми твоими молитвами сделай меня причастника Небесного Царства в Троице славимого Бога, Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0185", "section": "service", "who": "rubric", "text": "Глазные болезни, слепота"},
  {"id": "ru-mol-0186", "section": "service", "who": "rubric", "text": "^ Святому мученику Лонгину Сотнику, иже при Кресте Господни"},
  {"id": "ru-mol-0187", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:15"},
  {"id": "ru-mol-0188", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Лонгин,/ во страдании своем венец прият нетленный от Тебе, Бога нашего:/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "ru-mol-0189", "section": "service", "who": "reader", "text": "Мученик Твой, Господи, Лонгин подвигом своим венец нетленный получил от Тебя, Бога нашего; ибо он, имея силу Твою, мучителей низложил, сокрушил и демонов немощные дерзости. По молитвам его, Христе Боже, спаси души наши."},
  {"id": "ru-mol-0190", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "ru-mol-0191", "section": "service", "who": "rubric", "text": "Весело возрадовася Церковь/ в памяти днесь приснопамятнаго страдальца Лонгина, взывающи:// Ты моя держава, Христе, и утверждение."},
  {"id": "ru-mol-0192", "section": "service", "who": "reader", "text": "Радостно восторжествовала Церковь сегодня в день памяти достойного постоянного воспоминания мученика Лонгина, взывая: «Ты моя сила, Христос, и крепость»."},
  {"id": "ru-mol-0193", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0194", "section": "service", "who": "rubric", "text": "О святый мучениче Лонгине! Пилатом повелено тебе было с воинами стати на страже при кресте Господа Иисуса."},
  {"id": "ru-mol-0195", "section": "service", "who": "reader", "text": "О святой мученик Лонгин! Пилат тебе повелел с воинами стоять на страже у Креста Господа Иисуса."},
  {"id": "ru-mol-0196", "section": "service", "who": "reader", "text": "Ты же, болея глазами и исцелившись каплей крови Господа, капнувшей тебе в глаза, обрёл и духовное прозрение и, видя чудеса при распятии Господа происходившие, и землетрясение, и солнечное затмение, и мёртвых из гробов воскресение, во всеуслышание исповедал Иисуса Христа Сыном Божьим."},
  {"id": "ru-mol-0197", "section": "service", "who": "reader", "text": "И со стражей находясь у гроба Господа, и Воскресение Христово с трепетом видя, сребреники, даваемые синедрионом за сокрытие Воскресения, ты отверг и, Христа проповедав, был убит усечением головы."},
  {"id": "ru-mol-0198", "section": "service", "who": "reader", "text": "И после усечении главы некой вдове, у которой были больные глаза, во сне явился, и ей, обретшей почитаемую твою голову, даровал прозрение."},
  {"id": "ru-mol-0199", "section": "service", "who": "reader", "text": "Молим тебя, святой мученик Христов Лонгин, больным глазами окажи скорую помощь твою и исцели их, чтобы, освободившись от недуга своего, не захотели они видеть ничего, распаляющего сластолюбие, но к созерцанию духовной красоты устремились, славя Бога. Аминь."},
  {"id": "ru-mol-0200", "section": "service", "who": "rubric", "text": "^ Святому равноапостольному великому князю Владимиру, во Святом Крещении Василию, Крестителю Руси"},
  {"id": "ru-mol-0201", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:16"},
  {"id": "ru-mol-0202", "section": "service", "who": "rubric", "text": "Уподобился еси купцу, ищущему добраго бисера,/ славнодержавный Владимире,/ на высоте стола седя матере градов, богоспасаемаго Киева:/ испытуя же и посылая к Царскому граду/ уведети православную веру,/ обрел еси бесценный бисер — Христа,/ избравшаго тя яко втораго Павла,/ и оттрясшаго слепоту во святей купели,/ душевную вкупе и телесную./ Темже празднуем твое успение,/ людие твои суще:// моли спастися державы твоея Российския начальником и множеству владомых."},
  {"id": "ru-mol-0203", "section": "service", "who": "reader", "text": "Уподобился ты купцу, ищущему хороших жемчужин, славный властитель Владимир, восседая на высоком престоле матери городов, Богоспасаемого Киева: ибо испытывая и посылая в Царьград, узнать о православной вере, обрел ты бесценный жемчуг – Христа, избравшего тебя, как второго Павла; и, как он, стряхнул ты слепоту во святой купели, душевную, и вместе телесную. Потому мы, люди твои, празднуем твое успение; моли о спасении в державе твоей Российской начальствующих и множества ее граждан."},
  {"id": "ru-mol-0204", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0205", "section": "service", "who": "rubric", "text": "Подобствовав великому апостолу Павлу в сединах, всеславне Владимире,/ вся яко младенческая мудрования, яже о идолех тщания оставль,/ яко муж совершенный украсился еси Божественнаго Крещения багряницею./ И ныне Спасу Христу в веселии предстоя,// моли спастися державы Российския начальником и множеству владомых."},
  {"id": "ru-mol-0206", "section": "service", "who": "reader", "text": "Подобно великому Апостолу Павлу, в зрелых летах, всеславный Владимир, как детскую забаву, все мудрования и усердие к идолам оставив, ты, как муж совершенный, украсился порфирою Божественного крещения. И ныне Спасителю Христу в радости предстоя, моли о спасении в державе Российской начальствующих и множества ее граждан."},
  {"id": "ru-mol-0207", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0208", "section": "service", "who": "rubric", "text": "О великий и преславный угодниче Божий, богоизбранный и богопрославленный, равноапостольный княже Владимире, святое и великодейственное орудие всеблагаго Промысла о спасении народа Российскаго!"},
  {"id": "ru-mol-0209", "section": "service", "who": "reader", "text": "О великий и преславный угодник Божий, богоизбранный и богопрославленный, равноапостольный князь Владимир, святое и самое действенное орудие всеблагого Промысла о спасении Российского народа!"},
  {"id": "ru-mol-0210", "section": "service", "who": "reader", "text": "Ты отверг ложную веру и нечестие языческое, уверовал во Единого Истинного Триипостасного Бога и, восприняв святое Крещение, ты просветил светом Божественной веры и благочестия страну Российскую. Поэтому славя и благодаря Премилосердного Творца и Спасителя нашего, славим и благодарим тебя, великий пастырь и отче наш, потому что тобой познали спасительную веру Христову и крестились во имя Пресвятой и Пребожественной Троицы, той же верой избавились от праведного Божьего осуждения, вечного рабства диаволу и адового мучительства, той верой восприняли благодать усыновления Богу и надежду наследования Небесного блаженства."},
  {"id": "ru-mol-0211", "section": "service", "who": "reader", "text": "Ты — первейший наш вождь перед Начальником и Совершителем нашего вечного спасения, Господом Иисусом Христом, ты — ближайший предстатель перед Престолом Царя царствующих и усердный молитвенник и ходатай о нашей стране и о всех людях, ты — первейший виновник благословений и милостей Божьих, почивающих на нас."},
  {"id": "ru-mol-0212", "section": "service", "who": "reader", "text": "И что ещё скажем? Не может наш язык изобразить величие и высоту твоих благодеяний, которые излились на нас недостойных. Но, о наше неразумие и ослепление! Приняв столько благодеяний, ни во что же сочли их и удалились от спасительных твоих плодов."},
  {"id": "ru-mol-0213", "section": "service", "who": "reader", "text": "Омывшись от греха в купели Крещения и облачились в одежду чистоты и невинности, осквернив эту благодатную одежду постыдными действиями и помышлениями нашими. Отрекшись сатаны и злых духов его, снова порабощаемся ему, служа идолам наших страстей, миру, плоти и злым обычаям этого времени. Соединившись Христу, всегда оскорбляем Его нашими беззакониями, многообразными язвами гордости, зависти, злобы, злословия, невоздержания и пренебрежением ко Святой Церкви."},
  {"id": "ru-mol-0214", "section": "service", "who": "reader", "text": "Прилепились всецело к суетным благам, словно думая, что вечно будем пребывать на земле, не думаем о Небе, о душе, о смерти, о Суде, о нескончаемой вечности. Поэтому мы наводим на самих себя праведный гнев и осуждение Божье, вместе с тем оскорбляем и огорчаем твою отеческую любовь и попечение о нас, ты просветил нас святым Крещением, чтобы помочь нам получить Небесное блаженство и земное благоденствие, мы, неразумные, злым произволением нашим сами себя подвергаем адовым мукам и временным бедствиям!"},
  {"id": "ru-mol-0215", "section": "service", "who": "reader", "text": "Но, о всеблагой отец и просветитель наш, будь милостив к нашим немощам, долготерпелив к нашим грехам и неправдам, умоли Премилосердного Царя Небесного, да не прогневается сильно на нас и не погубит нас с нашими беззакониями, но да помилует и спасёт нас, Ему Единому известными способами. Да всадит в наши сердца спасительный страх Свой, да просветит Своей благодатью наш ум, чтобы мы могли увидеть бездну погибели, в которую стремимся, чтобы оставили пути нечестия и заблуждения, обратились на путь спасения и истины, чтобы неуклонно исполняли заповеди Божьи и уставы Святой Церкви."},
  {"id": "ru-mol-0216", "section": "service", "who": "reader", "text": "Моли, милосердный, Человеколюбца Бога, да покажет нам великую милость Свою, да избавит нас от нашествия иноплеменников, от внутренних нестроений, мятежей и раздоров, от голода, смертоносных болезней и от всякого зла, да подаст нам благоприятную погоду и плодоносие земле, да сохранит в судящих и начальствующих правду и милость, да даст духовным пастырям непорочность жизни и ревность о спасении пасомых, всем людям усердие в исполнении своих обязанностей, взаимную любовь и единомыслие, стремление ко благу отечества и Святой Церкви."},
  {"id": "ru-mol-0217", "section": "service", "who": "reader", "text": "Да распространит свет спасительной веры в нашей стране, во всех её концах, да обратит к правой вере неверующих, да упразднит все ереси и расколы, да, так пожив в мире на земле, сподобимся с тобой вечного блаженства, хваля и превознося Бога во веки веков. Аминь."},
  {"id": "ru-mol-0218", "section": "service", "who": "rubric", "text": "^ Святому великомученику Димитрию Солунскому"},
  {"id": "ru-mol-0219", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:17"},
  {"id": "ru-mol-0220", "section": "service", "who": "rubric", "text": "Велика обрете в бедах/ тя поборника вселенная, страстотерпче,/ языки побеждающа./ Якоже убо Лиеву низложил еси гордыню,/ и на подвиг дерзновенна сотворив Нестора,/ тако, святе Димитрие,/ Христу Богу молися// даровати нам велию милость."},
  {"id": "ru-mol-0221", "section": "service", "who": "reader", "text": "Великого в бедах защитника, язычников побеждающего, в тебе, страстотерпец, обрела вселенная. И как ты низверг гордыню Лия, на борьбу вдохновив Нестора, так, святой Димитрий, Христа Бога моли, да дарует Он нам великую милость."},
  {"id": "ru-mol-0222", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0223", "section": "service", "who": "rubric", "text": "Кровей твоих струями, Димитрие,/ Церковь Бог обагри,/ давый тебе крепость непобедимую,/ и соблюдая град твой невредим:// того бо еси утверждение."},
  {"id": "ru-mol-0224", "section": "service", "who": "reader", "text": "Потоками крови твоей, Димитрий, Церковь Бог обагрил, дав тебе силу непобедимую и сохраняя град твой невредимым, ибо ты – его утверждение."},
  {"id": "ru-mol-0225", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0226", "section": "service", "who": "rubric", "text": "Святый и славный великомучениче Христов Димитрие, скорый помощниче и теплый заступниче с верою притекающих к тебе!"},
  {"id": "ru-mol-0227", "section": "service", "who": "reader", "text": "Святой и славный великомученик Христов Димитрий, быстрый помощник и усердный заступник с верой прибегающих к тебе!"},
  {"id": "ru-mol-0228", "section": "service", "who": "reader", "text": "С дерзновением предстоящий перед Небесным Царём, испроси у Него прощение согрешений наших и дабы нам избавиться от всегубительной болезни, землетрясения, наводнения, огня, меча и вечной казни."},
  {"id": "ru-mol-0229", "section": "service", "who": "reader", "text": "Моли Его благость, да пощадит это город (эту обитель) и всякую христианскую страну."},
  {"id": "ru-mol-0230", "section": "service", "who": "reader", "text": "Испроси у Царя царствующих победу над врагами и их преодоление православным христианам, всей православной державе мир, тишину, твёрдость в вере и успешность в благочестии."},
  {"id": "ru-mol-0231", "section": "service", "who": "reader", "text": "Нам же, почитающим дорогую твою память, испроси благодатное укрепление на благие дела, да милостивое сотворив нашему Владыке Христу Богу здесь, сподобимся твоими молитвами наследовать Царство Небесное для вечного прославления Его со Отцом и Святым Духом. Аминь."},
  {"id": "ru-mol-0232", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Казанская»"},
  {"id": "ru-mol-0233", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:18"},
  {"id": "ru-mol-0234", "section": "service", "who": "rubric", "text": "Заступнице усердная,/ Мати Господа Вышняго,/ за всех молиши Сына Твоего Христа Бога нашего,/ и всем твориши спастися,/ в державный Твой покров прибегающим./ Всех нас заступи, о Госпоже Царице и Владычице,/ иже в напастех и в скорбех, и в болезнех обремененных грехи многими,/ предстоящих и молящихся Тебе умиленною душею/ и сокрушенным сердцем,/ пред пречистым Твоим образом со слезами,/ и невозвратно надежду имущих на Тя,/ избавления всех зол,/ всем полезная даруй,/ и вся спаси, Богородице Дево:// Ты бо еси Божественный покров рабом Твоим."},
  {"id": "ru-mol-0235", "section": "service", "who": "reader", "text": "Заступница усердная, Матерь Господа Всевышнего, за всех молишь Ты Сына Твоего, Христа Бога нашего, и содействуешь спасению всех, под мощный Твой покров прибегающих. Всех нас защити, о Госпожа, Царица и Владычица, пребывающих в напастях, и скорбях, и болезнях, обремененных грехами многими, предстоящих и молящихся Тебе с умиленною душою и сокрушенным сердцем, пред пречистым Твоим образом со слезами, и имеющих твердую надежду в Тебе на избавление от всех зол. Всем полезное даруй и всех спаси, Богородица Дева, ибо Ты – Божественный покров рабам Твоим."},
  {"id": "ru-mol-0236", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:19"},
  {"id": "ru-mol-0237", "section": "service", "who": "rubric", "text": "Притецем, людие, к тихому сему и доброму пристанищу,/ скорой Помощнице, готовому и теплому спасению, покрову Девы,/ ускорим на молитву и потщимся на покаяние:/ источает бо нам неоскудныя милости Пречистая Богородица,/ предваряет на помощь, и избавляет от великих бед и зол// благонравныя и богобоящияся рабы Своя."},
  {"id": "ru-mol-0238", "section": "service", "who": "reader", "text": "Прибегнем, люди, к тихому сему и доброму пристанищу, скорой Помощнице, готовому и теплому спасению, покрову Девы; поспешим на молитву и подвигнемся на покаяние: ибо источает нам неоскудевающие милости Пречистая Богородица, спешит на помощь и избавляет от великих бед и зол благочестивых и богобоязненных рабов Своих."},
  {"id": "ru-mol-0239", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0240", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице! Со страхом, верою и любовию пред честною и чудотворною иконою Твоею припадающе, молим Тя: не отврати лица Твоего от прибегающих к Тебе."},
  {"id": "ru-mol-0241", "section": "service", "who": "reader", "text": "О Пресвятая Госпожа Владычица Богородица! Со страхом, верой и любовью перед драгоценной и чудотворной Твоей иконой припадая, молим Тебя: не отврати Твоего лица от прибегающих к Тебе."},
  {"id": "ru-mol-0242", "section": "service", "who": "reader", "text": "Умоли, милосердная Матерь, Сына Твоего и Бога нашего, Господа Иисуса Христа, да сохранит в мире (в спокойствии) нашу страну, Церковь Свою Святую непоколебимую да сбережёт и от неверия, от ересей и раскола да избавит."},
  {"id": "ru-mol-0243", "section": "service", "who": "reader", "text": "Не имеем иной помощи, не имеем иной надежды, кроме Тебя, Пречистая Дева: Ты — всесильная для христиан Помощница и Заступница."},
  {"id": "ru-mol-0244", "section": "service", "who": "reader", "text": "Избавь же и всех, с верой к Тебе молящихся, от греховных падений, от покушения злых людей, от всяких искушений, скорбей, болезней, бед и от внезапной смерти."},
  {"id": "ru-mol-0245", "section": "service", "who": "reader", "text": "Даруй нам дух раскаяния о грехах, смирение сердца, чистые мысли, исправление от греховной жизни и оставление прегрешений, да все с благодарностью воспоют славу и милость Твою, которые Ты являешь над нами здесь на земле, сподобимся и Небесного Царствия, и там со всеми святыми прославим пречестное и великолепное имя Отца, и Сына, и Святого Духа во веки веков. Аминь."},
  {"id": "ru-mol-0246", "section": "service", "who": "rubric", "text": "^ Святителю Алексию, митрополиту Московскому, всея Руси чудотворцу"},
  {"id": "ru-mol-0247", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:20"},
  {"id": "ru-mol-0248", "section": "service", "who": "rubric", "text": "Яко апостолом сопрестольна,/ и врача предобра, и служителя благоприятна,/ к раце твоей честней притекающе, святителю Алексие Богомудре, чудотворче,/ сошедшеся, любовию в память твою светло празднуем,/ в песнех и пениих радующеся и Христа славяще,/ таковую благодать тебе даровавшаго исцелений// и граду твоему великое утверждение."},
  {"id": "ru-mol-0249", "section": "service", "who": "reader", "text": "К разделяющему престол с апостолами, и целителю прекрасному, и служителю угодному Богу, к раке твоей почитаемой приходим, святитель Алексий Богомудрый, чудотворец, собравшись с любовью в день памяти твоей светло празднуем, радуясь в псалмопениях и песнопениях духовных и прославляя Христа, даровавшего тебе такую благодать исцелений и городу твоему великую силу."},
  {"id": "ru-mol-0250", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0251", "section": "service", "who": "rubric", "text": "Божественнаго и пречестнаго святителя Христова,/ новаго чудотворца Алексия,/ верно вси поюще, людие, любовию да ублажим, яко пастыря великаго,/ служителя же и учителя премудра земли Российстей./ Днесь, в память его притекше,/ радостно возопием песнь Богоносному:/ яко имея дерзновение к Богу,/ многообразных нас избави обстояний, да зовем ти:// радуйся, утверждение граду нашему."},
  {"id": "ru-mol-0252", "section": "service", "who": "reader", "text": "Божественного и особо почитаемого святителя Христова, нового чудотворца Алексия, с верой все воспевающе, люди, с любовью прославим, как великого пастыря, служителя и учителя премудрого земли Российской. Сегодня, собравшись в день его памяти, с радостью воспоем песнь Богоносному: как имеющий дерзновение к Богу, от многообразных нас избавь бедствий, да взываем к тебе: «Радуйся, сила города нашего»."},
  {"id": "ru-mol-0253", "section": "service", "who": "rubric", "text": "Молитва:21"},
  {"id": "ru-mol-0254", "section": "service", "who": "rubric", "text": "О пречестная и священная главо и благодати Святаго Духа исполненная, Спасово со Отцем обиталище, великий архиерее, теплый наш заступниче, святителю Алексие!"},
  {"id": "ru-mol-0255", "section": "service", "who": "reader", "text": "О пречестная и священная глава и благодати Святого Духа наполненная, жилище Спаса с Отцом, великий архиерей, усердный наш заступник, святитель Алексей!"},
  {"id": "ru-mol-0256", "section": "service", "who": "reader", "text": "Предстоящий у Престола всех Царя и наслаждающийся светом Единосущной Троицы, и, подобно херувимам, с ангелами возглашающий Трисвятую песнь, великое и непостижимое дерзновение имеющий к Всемилостивому Владыке, молись спасти людей твоей паствы, единственный родной тебе народ."},
  {"id": "ru-mol-0257", "section": "service", "who": "reader", "text": "Незыблемость святых церквей укрепи, архиереев благообразием святительства укрась; монашествующих к подвигам истинного жизненного пути укрепи."},
  {"id": "ru-mol-0258", "section": "service", "who": "reader", "text": "Этот город (или: это село; если в монастыре: эту святую обитель) и все города и страны хорошо сохрани и святую непорочную веру тем соблюсти Господа умоли."},
  {"id": "ru-mol-0259", "section": "service", "who": "reader", "text": "Весь мир примири, от голода и погибели избавь нас и от нападения иноплеменных сохрани нас."},
  {"id": "ru-mol-0260", "section": "service", "who": "reader", "text": "Старых утешь, юных научи, безумных умудри, вдов помилуй, заступись за сирот, младенцев воспитай, пленных возврати, больных исцели и везде усердно призывающих тебя и с верой прибегающих к раке честных и многоцелебных твоих мощей, с усердием припадающих и молящихся к тебе от всяких напастей и бед ходатайством твоим освободи, да взываем к тебе: о Богоизбранный пастырь, самая светлая звезда тверди невещественной, таинственного Сиона башня неприступная, миром благоухающий райский цветок, золотые уста Слова, прославление Москвы, украшение всей России!"},
  {"id": "ru-mol-0261", "section": "service", "who": "reader", "text": "Моли о нас Всещедрого и Человеколюбивого Христа Бога нашего, да в день страшного пришествия Его избавит нас от стояния по левую руку от Него и причастниками радости святых сотворит со всеми святыми во веки. Аминь."},
  {"id": "ru-mol-0262", "section": "service", "who": "rubric", "text": "^ Святому мученику и архидиакону Лаврентию Римскому"},
  {"id": "ru-mol-0263", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:22"},
  {"id": "ru-mol-0264", "section": "service", "who": "rubric", "text": "Мученик Твой, Господи, Лаврентий/ во страдании своем венец прият нетленный от Тебе, Бога нашего,/ имеяй бо крепость Твою,/ мучителей низложи,/ сокруши и демонов немощныя дерзости./ Того молитвами// спаси души наша."},
  {"id": "ru-mol-0265", "section": "service", "who": "reader", "text": "Мученик Твой, Господи, Лаврентий подвигом своим венец нетленный получил от Тебя, Бога нашего; ибо он, имея силу Твою, мучителей низложил, сокрушил и демонов немощные дерзости. По молитвам его, Христе Боже, спаси души наши."},
  {"id": "ru-mol-0266", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "ru-mol-0267", "section": "service", "who": "rubric", "text": "Огнем Божественным распалив сердце твое,/ огнь страстей до конца испепелил еси,/ страдальцев утверждение, Богоносе мучениче Лаврентие,/ и в страданиих вопиял еси верно:// ничтоже мя разлучит любве Христовы."},
  {"id": "ru-mol-0268", "section": "service", "who": "reader", "text": "Огнем Божественным воспламенив сердце свое, ты до конца испепелил огонь страстей, исповедников веры сила, Богоносный мученик Лаврентий, и в страданиях ты взывал с верой: «Ничто не разлучит меня от любви Христовой» (Рим.8:39)."},
  {"id": "ru-mol-0269", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0270", "section": "service", "who": "reader", "text": "О пресвятой и предивный страстотерпец Христов, архидиакон Лаврентий! Восхваляя веру и страдания твои, почитаем победу и венценосное прохождение твоё чрез горящие угли из тьмы века сего к незаходящему свету Престола Величества Божия. Поэтому молим тебя: как ты некогда прибегавших с верой к твоему покрову твоими чудесами укрепил, прими и нас под твой покров, и в болезнях, и в печалях наших будь заступником нам, и как от слепоты телесных очей Крискентиана исцелил прикосновением рук, так исцели своим предстательством у Престола Божия и нашу душевную слепоту. Обрати своё внимание на наше телесное и душевное расслабление и укрепи нас бдительностью против наших видимых и невидимых врагов, удручающих нас напастями. Да с твоей помощью путь временной этой жизни пройдя, не побеждённые бедами и скорбями, и всякими злыми невзгодами, достигнем недосягаемой славы величества Божия, где ты, предстоя, молишься с дерзновением за людей прибегающих с верой к тебе и воспевающих дивного во святых Бога Израиля во веки веков. Аминь."},
  {"id": "ru-mol-0271", "section": "service", "who": "rubric", "text": "Зубная боль"},
  {"id": "ru-mol-0272", "section": "service", "who": "rubric", "text": "^ Священномученику Антипе, епископу Пергамскому"},
  {"id": "ru-mol-0273", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:23"},
  {"id": "ru-mol-0274", "section": "service", "who": "rubric", "text": "И нравом причастник,/ и престолом наместник апостолом быв,/ деяние обрел еси, Богодухновенне,/ в видения восход:/ сего ради, слово истины исправляя,/ и веры ради пострадал еси даже до крове,/ священномучениче Антипо,/ моли Христа Бога// спастися душам нашим."},
  {"id": "ru-mol-0275", "section": "service", "who": "reader", "text": "И нравам Апостольским сопричастником, и престола их наследником став, делами ты, Богодухновенный, восхождения к созерцанию достиг; потому слово истины право возвещая, ты за веру пострадал до крови, священномученик Антипа, ходатайствуй пред Христом Богом о спасении душ наших."},
  {"id": "ru-mol-0276", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "ru-mol-0277", "section": "service", "who": "rubric", "text": "Апостолов сопрестольник и святителей украшение/ был еси, блаженне,/ мученически прославився,/ возсиял еси, якоже солнце, всех просвещая,/ Антипо священне,/ разрушил еси безбожия нощь глубокую./ Сего ради тя почитаем,/ яко Божественнаго суща священномученика// и целеб подателя."},
  {"id": "ru-mol-0278", "section": "service", "who": "reader", "text": "Сопрестольник с апостолами и украшение святителям ты был, блаженный, мученически прославился и воссиял ты, как солнце, просвещая всех, святой Антипа, разогнав глубокую тьму безбожия. Поэтому мы почитаем тебя, как святого священномученика и подателя исцелений."},
  {"id": "ru-mol-0279", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0280", "section": "service", "who": "rubric", "text": "О преславный священномучениче Антипо и скорый помощниче христианом в болезнех! Верую от всея души и помышления, яко дадеся тебе от Господа дар болящия исцеляти, недугующия врачевати и разслабленныя укрепляти."},
  {"id": "ru-mol-0281", "section": "service", "who": "reader", "text": "О преславный священномученик Антипа и быстрый помощник христианам в болезнях! Верую от всей души и всего разума, что дан тебе от Господа дар исцелять больных, недугующих врачевать и расслабленных укреплять."},
  {"id": "ru-mol-0282", "section": "service", "who": "reader", "text": "Поэтому к тебе, как благодатному врачу болезней, я, немощный (немощная) прибегаю и, твой должным образом почитаемый образ с благоговением лобызая, молюсь: твоим предстательством у Царя Небесного испроси мне, болящему (болящей) исцеление от удручающей меня зубной болезни, если и недостоин (недостойна) тебя, самого благостного отца и постоянного моего заступника, но ты, был подражателем Божьего человеколюбия, сотвори меня достойным (достойной) твоего заступничества чрез моё обращение от злых дел к благой жизни, уврачуй обильно данной тебе благодатью язвы и раны души и тела моего, даруй мне здоровье и спасение и во всём доброе содействие, да, так спокойную и безмятежную жизнь пожив во всяком благочестии и чистоте, сподоблюсь со всеми святыми славить всесвятое имя Отца, и Сына, и Святого Духа. Аминь."},
  {"id": "ru-mol-0283", "section": "service", "who": "rubric", "text": "Болезни сердца"},
  {"id": "ru-mol-0284", "section": "service", "who": "rubric", "text": "^ Святителю Иоасафу, епископу Белгородскому"},
  {"id": "ru-mol-0285", "section": "service", "who": "rubric", "text": "Тропарь, глас 3-й:24"},
  {"id": "ru-mol-0286", "section": "service", "who": "rubric", "text": "Святителю Христу Богу возлюбленне,/ правило веры и образ милосердия людем был еси,/ бдением же, постом и молитвою,/ яко светильник пресветлый просиял еси,/ и прославлен от Бога явился еси;/ телом убо в нетлении почивая,/ духом же престолу Божию предстоя,/ чудеса преславно источаеши./ Моли Христа Бога,// да утвердит нас в Православии и благочестии/ и спасет души наша."},
  {"id": "ru-mol-0287", "section": "service", "who": "reader", "text": "Святитель, Христом Богом возлюбленный, ты был образцом веры и примером милосердия для людей, бдением же, постом и молитвой, как преяркий светильник просиял ты, и был прославлен Богом, ибо телом ты почиваешь в нетлении, духом же Престолу Божию предстоишь и чудеса удивительно источаешь. Моли Христа Бога, да утвердит нас в Православии и благочестии и спасет души наши."},
  {"id": "ru-mol-0288", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0289", "section": "service", "who": "rubric", "text": "Многоразличныя подвиги жития твоего кто исповесть?/ Многообразныя милости Божия тобою явленныя кто исчислит?/ Дерзновение же твое у Пречистыя Богородицы и Всещедраго Бога добре ведуще,/ во умилении сердечнем зовем ти:/ не лиши и нас твоея помощи и заступления,// святителю Христов и чудотворче Иоасафе."},
  {"id": "ru-mol-0290", "section": "service", "who": "reader", "text": "О многоразличных подвигах жития твоего кто поведает? Многообразные милости Божии тобой явленные кто сосчитает? Дерзновение же твое ко Пречистой Богородице и Всещедрому Богу прекрасно зная, с сердечным сокрушением взываем к тебе: «Не лиши и нас твоей помощи и защиты, святитель Христов и чудотворец Иоасаф»."},
  {"id": "ru-mol-0291", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0292", "section": "service", "who": "rubric", "text": "О угодниче Божий святителю Иоасафе! Из глубины сердца взываем к тебе раби Божии (имена), огради нас от соблазна, ересей и расколов, научи горняя мудрствовати, рассеянный ум наш просвети и на путь истины направи, охладевшее сердце согрей любовию ко ближнему и ревностию ко исполнению велений Божиих, грехом и нерадением ослабленную волю нашу оживотвори благодатию Духа Всесвятого."},
  {"id": "ru-mol-0293", "section": "service", "who": "reader", "text": "О угодник Божий святитель Иоасаф! Из глубины сердца взываем к тебе рабы Божии (имена), огради нас от соблазна, ересей и расколов, научи думать возвышенно, рассеянный ум наш просвети и на путь истины направь, охладевшее сердце согрей любовью к ближнему и ревностью к исполнению повелений Божиих, ослабленную волю нашу грехом и нерадением оживотвори благодатью Всесвятого Духа."},
  {"id": "ru-mol-0294", "section": "service", "who": "reader", "text": "Да твоему пастырскому голосу последуя, сохраним в чистоте и правде души наша, и так с Божьей помощью, Небесного Царства достигнем, где вместе с тобой прославим пречестное и великолепное имя Отца, и Сына, и Святого Духа во веки веков. Аминь."},
  {"id": "ru-mol-0295", "section": "service", "who": "rubric", "text": "Немота"},
  {"id": "ru-mol-0296", "section": "service", "who": "rubric", "text": "^ Преподобному Иоанну Рыльскому"},
  {"id": "ru-mol-0297", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:25"},
  {"id": "ru-mol-0298", "section": "service", "who": "rubric", "text": "Покаяния основание, прописание умиления,/ образ утешения, духовнаго совершения,/ равноангельное житие твое бысть, преподобне./ В молитвах убо и пощениих, и в слезах пребывавый,/ отче Иоанне,// моли Христа Бога о душах наших."},
  {"id": "ru-mol-0299", "section": "service", "who": "reader", "text": "Покаяния основанием, смирения изложением, примером утешающим, духовно совершенной, подобной ангельской жизнь твоя была, преподобный. В молитвах, пощении и в слезах пребывавший, отче Иоанн, моли Христа Бога о душах наших."},
  {"id": "ru-mol-0300", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0301", "section": "service", "who": "rubric", "text": "Ангельскому житию поревновав, преподобне,/ вся земная оставив, ко Христу притекл еси,/ и того заповедьми ограждаяся, явился еси столп непоколебимь от вражиих нападений. Тем зовем ти:// радуйся, отче Иоанне, светило пресветлое."},
  {"id": "ru-mol-0302", "section": "service", "who": "reader", "text": "Ангельскому житию подражая, преподобный, все земное оставив, ты пришел ко Христу и Его заповедями защищаясь, ты стал непоколебимой крепостью против вражеских нападений. Потому взываем к тебе: «Радуйся, отче Иоанн, светило преяркое»."},
  {"id": "ru-mol-0303", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0304", "section": "service", "who": "rubric", "text": "О преподобне и богоносне отче наш Иоанне, зрителю неизреченныя славы в Небеснем Царствии и помощниче благодатный всем к тебе притекающим, не остави места сего, на немже труды и подвиги о Христе подъял еси и землю слезами твоими оросил еси!"},
  {"id": "ru-mol-0305", "section": "service", "who": "reader", "text": "О преподобный и богоносный отец наш Иоанн, зритель неизреченной славы в Небесном Царствии и благодатный помощник всем к тебе прибегающим, не оставь этого места, где ты труды и подвиги переносил ради Христа и землю слезами твоими оросил!"},
  {"id": "ru-mol-0306", "section": "service", "who": "reader", "text": "Да пребудет твоя обитель, в которой Бог благоволил почивать святым твоим мощам, незыблема от ухищрений видимых и невидимых врагов. Укрепи в делании добра твоих детей, которых в обители своей ты собрал, так да познают призвание своё и последуют твоим стопам. Страну нашу в мире сбереги. Православным людям в борьбе с врагами помоги победить."},
  {"id": "ru-mol-0307", "section": "service", "who": "reader", "text": "Посети с небесной высоты всех, с верой к тебе прибегающих и просящих твоего твёрдого заступничества; в море плавающих направь, волнения жизненного моря утешь, церковное раздоры укроти, мир всему миру у Господа испроси, болящих исцели спасительным посещением, скорбных утешь благодатью, для всех будь всем, как ты был во время земной жизни твоей."},
  {"id": "ru-mol-0308", "section": "service", "who": "reader", "text": "Вознеси о нас к Богу молитву, потому что дана тебе благодать молиться за нас, так да сподобимся твоим ходатайством получить вечное блаженство вместе с тобой и всеми святыми во Христе Иисусе, Господе нашим, Которому подобает вся слава, честь и поклонение со Отцом и Святым Духом во веки веков. Аминь."},
  {"id": "ru-mol-0309", "section": "service", "who": "rubric", "text": "Потеря слуха и болезни ушей"},
  {"id": "ru-mol-0310", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице перед Ее иконой «Нечаянная радость»"},
  {"id": "ru-mol-0311", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:26"},
  {"id": "ru-mol-0312", "section": "service", "who": "rubric", "text": "Днесь, вернии людие, духовно торжествуем,/ прославляюще Заступницу усердную рода христианскаго,/ и притекающе к пречистому Ея образу, взываем сице:/ о, Премилостивая Владычице Богородице,/ подаждь нам нечаянную радость,/ обремененным грехи и скорбьми многими,/ и избави нас от всякаго зла,// молящи Сына Твоего, Христа Бога нашего,/ спасти души наша."},
  {"id": "ru-mol-0313", "section": "service", "who": "reader", "text": "Сегодня, верующие люди, духовно торжествуем, прославляя Защитницу усердную христианского рода и прибегая к пречистому Её образу взываем так: о Премилостивая Владычица Богородица, подай нам нежданную радость, обремененным грехами и множеством скорбей, и избавь нас от всякого зла, моля Сына Твоего, Христа Бога нашего о спасении наших душ."},
  {"id": "ru-mol-0314", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:"},
  {"id": "ru-mol-0315", "section": "service", "who": "rubric", "text": "Не имамы иныя помощи,/ не имамы иныя надежды,/ разве Тебе, Владычице./ Ты нам помози,/ на Тебе надеемся,/ и Тобою хвалимся,/ Твои бо есмы раби,// да не постыдимся."},
  {"id": "ru-mol-0316", "section": "service", "who": "reader", "text": "Не имеем иной помощи, не имеем иной надежды, кроме Тебя, Владычица. Ты нам помоги: на Тебя надеемся и Тобою хвалимся, ибо мы – Твои рабы; да не постыдимся!"},
  {"id": "ru-mol-0317", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0318", "section": "service", "who": "rubric", "text": "О Пресвятая Дево, Всеблагаго Сына Мати Всеблагая, града сего покрове, всех сущих во гресех, скорбех, бедах и болезнех верная Предстательнице и Заступнице!"},
  {"id": "ru-mol-0319", "section": "service", "who": "reader", "text": "О Пресвятая Дева, Всеблагого Сына Всеблагая Матерь, этого города покров, всех находящихся в грехах, скорбях, бедах и болезнях верная Предстательница и Заступница!"},
  {"id": "ru-mol-0320", "section": "service", "who": "reader", "text": "Прими это молебное пение от нас, недостойных рабов Твоих возносимое Тебе; и как некогда грешника, на каждый день многократно пред честной иконой Твоей молившегося, Ты не презрела, но неожиданную радость покаяния ему даровала, и усердным ходатайством к Сыну Твоему для прощения грешника преклонила Его, так и ныне не презри наших молитв, недостойных рабов Твоих, но умоли Сына Твоего и Бога нашего, да и всем нам, с верой и умилением пред цельбоносным образом Твоим поклоняющимся, по собственной потребности каждого неожиданную радость дарует."},
  {"id": "ru-mol-0321", "section": "service", "who": "reader", "text": "Да все на небе и на земле видят Тебя как неизменную и неустрашимую Предстательницу христианского рода, и, зная это, славят Тебя и с Тобой Сына Твоего со Безначальным Его Отцом и Единосущным Его Духом, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0322", "section": "service", "who": "rubric", "text": "Болезни чревные, грыжа"},
  {"id": "ru-mol-0323", "section": "service", "who": "rubric", "text": "^ Великомученику Артемию"},
  {"id": "ru-mol-0324", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:27"},
  {"id": "ru-mol-0325", "section": "service", "who": "rubric", "text": "Истинною бо Христовою верою/ утверждься, страстотерпче,/ мучителя злочестива царя/ победил еси со идольским того возношением./ Тем от Царя Великаго, вечно царствующаго,/ пресветлым венцем победным одарен бысть,/ вся исцеляяй болящия и призывающия тя, Артемие великий,/ моли Христа Бога// спасти души наша."},
  {"id": "ru-mol-0326", "section": "service", "who": "reader", "text": "Истинной верой Христовой укрепившись, страстотерпец, нечестивого царя-мучителя победил ты с его идольскими жертвоприношениями. Потому от Царя Великого, вечно царствующего, пресветлым венцом победы был одарен. Исцеляющий всех болеющих и призывающих тебя, Артемий великий, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0327", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0328", "section": "service", "who": "rubric", "text": "Благочестиваго и венценоснаго мученика,/ на враги победы вземшаго одоление,/ сошедшеся, достойно песньми восхвалим Артемия,/ превеликаго в мученицех,/ чудес же дателя пребогатаго,// молится бо Господу о всех нас."},
  {"id": "ru-mol-0329", "section": "service", "who": "reader", "text": "Благочестивого и венценосного мученика, захватившего трофей победы над врагом, собравшись, по достоинству прославим молитвенными песнопениями Артемия, превеликого мученика, щедрого дарователя чудес, ибо он молится Господу обо всех нас."},
  {"id": "ru-mol-0330", "section": "service", "who": "rubric", "text": "Славник, глас 2-й:"},
  {"id": "ru-mol-0331", "section": "service", "who": "rubric", "text": "Разумнаго светильника веры, Артемия почтим. Яко обличи царя мерзкаго, и кровию мучения его Церковь Бог обагри. Тем и прият исцелений благодать независтную исцеляти недуги верно приходящих к раце мощей его."},
  {"id": "ru-mol-0332", "section": "service", "who": "reader", "text": "Разумного светильника веры, почтим Артемия. Потому что обличил мерзкого царя, и кровью его мучения Бог обагрил Церковь. Поэтому и принял обильную благодать исцелений исцелять недуги с верой приходящих к раке мощей его."},
  {"id": "ru-mol-0333", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0334", "section": "service", "who": "rubric", "text": "Святый мучениче Артемие! Призри с небеснаго чертога на требующих твоея помощи и не отвергни прошений наших, но, яко присный благодетель и ходатай наш, моли Христа Бога, да, человеколюбив и многомилостив сый, сохранит нас от всякаго лютаго обстояния: от труса, потопа, огня, меча, нашествия иноплеменников и междоусобныя брани."},
  {"id": "ru-mol-0335", "section": "service", "who": "reader", "text": "Святой мученик Артемий! Обрати своё внимание с небесного жилища на требующих твоей помощи и не отвергни наших прошений, но, как постоянный благодетель и ходатай за нас, моли Христа Бога, потому что Он человеколюбив и многомилостив, сохранит нас от всяких злых невзгод: от землетрясения, наводнения, огня, меча, нашествия иноплеменников и междоусобной войны."},
  {"id": "ru-mol-0336", "section": "service", "who": "reader", "text": "Да не осудит нас грешных по беззакониям нашим, и да не обратим во зло блага, которые нам даруются от Всещедрого Бога, но во славу святого Его имени и в прославление незыблемого твоего заступничества."},
  {"id": "ru-mol-0337", "section": "service", "who": "reader", "text": "Да молитвами твоими подаст нам Господь мир в помыслах, воздержание от пагубных страстей и от всякой скверны и да укрепит во всём мире Свою Единую Святую, Соборную и Апостольскую Церковь, которую Он приобрёл драгоценной Своей Кровью."},
  {"id": "ru-mol-0338", "section": "service", "who": "reader", "text": "Молись прилежно, святой мученик, да благословит Христос Бог державу, да утвердит во святой Своей Православной Церкви живой дух правильной веры и благочестия, чтобы все члены её, чистые от суемудрия и суеверия, в духе и истине поклонялись Ему и усердно пеклись о соблюдении Его заповедей, чтобы мы всё в мире и благочестии прожили в этом веке и достигли блаженной вечной жизни на небесах, благодатью Господа нашего Иисуса Христа, Которому подобает вся слава, честь и держава со Отцом и Святым Духом, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0339", "section": "service", "who": "rubric", "text": "^ Преподобному Серафиму Саровскому"},
  {"id": "ru-mol-0340", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:28"},
  {"id": "ru-mol-0341", "section": "service", "who": "rubric", "text": "От юности Христа возлюбил еси, блаженне,/ и Тому Единому работати пламенне вожделев,/ непрестанною молитвою и трудом в пустыни подвизался еси,/ умиленным же сердцем любовь Христову стяжав,/ избранник возлюблен Божия Матере явился еси./ Сего ради вопием ти:// спасай нас молитвами твоими, Серафиме, преподобне отче наш."},
  {"id": "ru-mol-0342", "section": "service", "who": "reader", "text": "От юности ты возлюбил Христа, блаженный, и, Ему Одному служить пламенно возжелав, непрестанною молитвою и трудом в пустыни подвизался, и умиленным сердцем любовь Христову стяжав, избранником возлюбленным Божией Матери явился. Потому мы взываем тебе: «Спасай нас молитвами твоими, Серафим, преподобный отче наш!»"},
  {"id": "ru-mol-0343", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0344", "section": "service", "who": "rubric", "text": "Мира красоту и яже в нем тленная оставив, преподобне,/ в Саровскую обитель вселился еси,/ и тамо ангельски пожив,/ многим путь был еси ко спасению,/ сего ради и Христос тебе, отче Серафиме, прослави/ и даром исцелений и чудес обогати./ Темже вопием ти:// радуйся, Серафиме, преподобне отче наш."},
  {"id": "ru-mol-0345", "section": "service", "who": "reader", "text": "Мира красоту и все, что в нем тленного, оставив, преподобный, в Саровскую обитель ты вселился и, там ангельски пожив, стал для многих путем ко спасению. Оттого и Христос тебя, отче Серафим, прославил и даром исцелений и чудес обогатил. Потому мы взываем тебе: «Радуйся, Серафим, преподобный отче наш!»"},
  {"id": "ru-mol-0346", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0347", "section": "service", "who": "rubric", "text": "О пречудный отче Серафиме, великий Саровский чудотворче, всем прибегающим к тебе скоропослушный помощниче!"},
  {"id": "ru-mol-0348", "section": "service", "who": "reader", "text": "О пречудный отец Серафим, великий Саровский чудотворец, всем прибегающим к тебе скоро отзывающийся на просьбы помощник!"},
  {"id": "ru-mol-0349", "section": "service", "who": "reader", "text": "Во дни твоей земной жизни никто от тебя лишенным и неутешным не уходил, но всем в наслаждение было видеть твоё лицо и слышать благосклонный голос твоих слов. К этому и дар исцелений, дар прозрения, дар немощных душ врачевания в тебе обильно стал явлен."},
  {"id": "ru-mol-0350", "section": "service", "who": "reader", "text": "Когда призвал тебя Бог от земных трудов к Небесному упокоению, твоя любовь не перестала быть с нами, и нельзя перечислить всех твоих чудес, умножающихся, словно небесные звёзды: поэтому во всех концах нашей земли людям Божьим являешься и даруешь им исцеления."},
  {"id": "ru-mol-0351", "section": "service", "who": "reader", "text": "Посему и мы взываем к тебе: о самый радостный и кроткий угодник Божий, дерзновенный к Нему молитвенник, никогда призывающих тебя не отвергающий, вознеси о нас крепкую твою молитву к Господу Сил, да дарует нам всё необходимое в этой жизни и всё полезное для душевного спасения, да оградит нас от падений греховных и научит нас истинному покаянию, чтобы беспрепятственно войти нам в вечное Небесное Царство, где ты ныне в незаходимой сияешь славе, и там воспевать со всеми святыми Живоначальную Троицу до скончания века. Аминь."},
  {"id": "ru-mol-0352", "section": "service", "who": "rubric", "text": "^ Преподобному Феодору Студиту"},
  {"id": "ru-mol-0353", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:29"},
  {"id": "ru-mol-0354", "section": "service", "who": "rubric", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче,/ монашествующих Богодухновенное удобрение,/ Феодоре премудре,/ ученьми твоими вся просветил еси,/ цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "ru-mol-0355", "section": "service", "who": "reader", "text": "Православия наставник, благочестия учитель и чистоты, светильник вселенной, архиереев Богодухновенное украшение, Феодор премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0356", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0357", "section": "service", "who": "rubric", "text": "Постническое и равноангельное житие твое/ страдальческими уяснил еси подвиги/ и Ангелом совсельник, Богоблаженне, явился еси, Феодоре./ С ними Христу Богу моляся// не престай о всех нас."},
  {"id": "ru-mol-0358", "section": "service", "who": "reader", "text": "Постническую и подобную Ангелам жизнь твою ты прославил мученическим подвигом и поселился вместе с Ангелами, Богоблаженный Феодор, с ними же не переставай молиться Христу Богу обо всех нас."},
  {"id": "ru-mol-0359", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0360", "section": "service", "who": "rubric", "text": "О святый Феодоре, исповедник Православия, закона Божия ревнитель, наставник правой веры, помози нам и призри на нас, с верою и усердием прибегающих к тебе!"},
  {"id": "ru-mol-0361", "section": "service", "who": "reader", "text": "О святой Феодор, исповедник Православия, ревнитель закона Божия, наставник истинной веры, помоги нам и обрати своё внимание на нас, с верой и с усердием прибегающих к тебе!"},
  {"id": "ru-mol-0362", "section": "service", "who": "reader", "text": "От царей-иконоборцев за почитание святых икон оковы, изгнание, заточение ты претерпел, преподобный, и множество тяжких ран и жестоких ударов, от которых и болезнь нестерпимую получил."},
  {"id": "ru-mol-0363", "section": "service", "who": "reader", "text": "Великий и достойный удивления Феодор, до конца скорби претерпев, и нам, обуреваемым невзгодами и тревогами житейскими, подай стойкость душевную и телесную для борьбы с бедами и для одоления страстей и козней вражьих."},
  {"id": "ru-mol-0364", "section": "service", "who": "reader", "text": "Моли о нас Милосердного Господа, верный раб Божий Феодор, да избавит Он нас от ожесточения и холода сердца, и дарует нам кротость, безгневие, незлобие, смирение и любовь. Мы, видя твою помощь, прославим Господа и Спасителя нашего Иисуса Христа, и тебя, благодетеля нашего, возблагодарим, с благоговением почитая память твою."},
  {"id": "ru-mol-0365", "section": "service", "who": "reader", "text": "О всеми восхваляемый, преподобный Феодор, своим учением и песнопениями своими напоивший и обрадовавший Церковь Божию, и нас, ослеплённых умом от соблазнов и суеты этого мира, просвети познанием истины и избавь от заблуждений и сомнений, чтобы не согласовывать нам свои действия с деяниями этого века."},
  {"id": "ru-mol-0366", "section": "service", "who": "reader", "text": "О угодник Христов Феодор, получивший от Бога благодать исцеления недугующих, а наибольше страждущих желудком, уврачуй и нас, одержимых различными недугами и исцели болящих желудком и подай нам здоровье, бодрость и душевный мир. Не отвергни нас, прибегающих к тебе, но заступись и помоги нам."},
  {"id": "ru-mol-0367", "section": "service", "who": "reader", "text": "Будь представителем нашим перед Спасителем нашим, обрати своё внимание на наши моления и исполни наши прошения, да укрепляемые тобою, в трудах и добрых делах совершим мы наш жизненный путь и сподобимся войти в Царство Небесное, да вместе с тобой восхвалим и прославим Господа и Спасителя нашего Иисуса Христа, со Безначальным Его Отцом и с Пресвятым Духом, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0368", "section": "service", "who": "rubric", "text": "^ Праведному Артемию Веркольскому"},
  {"id": "ru-mol-0369", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:30"},
  {"id": "ru-mol-0370", "section": "service", "who": "rubric", "text": "Вышняго повелением,/ тученосным облаком небо помрачившим,/ и молниям блистающим,/ грому же возшумевшу с прещением,/ испустил еси душу твою в руце Господеви,/ премудре Артемие,/ и ныне предстоиши Престолу Владыки всех,/ иже верою и любовию приходящим к тебе,/ подая исцеление всем неотложно,/ и моляся Христу Богу,// спастися душам нашим."},
  {"id": "ru-mol-0371", "section": "service", "who": "reader", "text": "По воле Всевышнего, грозовым облаком небо помрачившего, в блистании молний и угрожающем шуме грома ты отпустил душу свою в руки Господа, премудрый Артемий, и сейчас предстоишь Престолу Владыки всех, с верою и любовью приходящим к тебе подавая исцеление без отлагательств и молясь Христу Богу о спасении наших душ."},
  {"id": "ru-mol-0372", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0373", "section": "service", "who": "rubric", "text": "Возсия днесь пресветлая память премудраго Артемия;/ Богоданная благодать яко реки изливает от целебных мощей его дивная исцеления,/ имиже от многоразличных недуг избавляемся,/ с верою приемлюще я, и взывающе:// радуйся, Артемие Богомудре."},
  {"id": "ru-mol-0374", "section": "service", "who": "reader", "text": "Воссияла сегодня пресветлая память премудрого Артемия. Богоданная благодать как реки изливает от врачующих мощей его удивительные исцеления, которыми мы избавляемся от многоразличных болезней, с верой принимая их и взывая: «Радуйся, Артемий Богомудрый»."},
  {"id": "ru-mol-0375", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0376", "section": "service", "who": "rubric", "text": "Святый угодниче Божий, праведный Артемие, присный хранителю святыя веры Православныя и близкий защитниче всего севернаго края Российския страны!"},
  {"id": "ru-mol-0377", "section": "service", "who": "reader", "text": "Святой угодник Божий, праведный Артемий, истинный хранитель святой Православной веры и близкий защитник всего северного края России!"},
  {"id": "ru-mol-0378", "section": "service", "who": "reader", "text": "Обрати своё милостивое внимание на усердную молитву нас грешных и твоим твёрдым предстательством испроси нам у Господа прощение согрешений наших, преуспевание в вере и благочестии и ограждение от диавольских козней."},
  {"id": "ru-mol-0379", "section": "service", "who": "reader", "text": "Моли Господа, да сохранит в здравии и подлинном благополучии верных людей Своих, да подаст стране нашей мир и тишину, а нам нелицемерное послушание, да сподобит всех нас получить после христианской кончины Небесное Царство, где все праведные вместе с тобой, вечно славят Отца и Сына и Святого Духа. Аминь."},
  {"id": "ru-mol-0380", "section": "service", "who": "rubric", "text": "Болезни ног"},
  {"id": "ru-mol-0381", "section": "service", "who": "rubric", "text": "^ Святому праведному Симеону Верхотурскому"},
  {"id": "ru-mol-0382", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:31"},
  {"id": "ru-mol-0383", "section": "service", "who": "rubric", "text": "Мирскаго мятежа бегая, все желание обратил еси к Богу,/ да в видения восход обрящеши горе,/ отнюдуже не уклонився в лукавствия сердца,/ но очистив душу и тело,/ приял еси благодать точити цельбы верным и неверным,/ притекающим к тебе, праведный Симеоне./ Темже, по данному ти дару,/ испроси у Христа Бога исцеление нам, болящим душевными страстьми,// и моли спасти души наша."},
  {"id": "ru-mol-0384", "section": "service", "who": "reader", "text": "Избегая мирской суеты, ты обратил все устремление к Богу, и, восходя в созерцаниях ввысь к небу, оттуда ты не уклонился сердцем к лукавому, но, очистив душу и тело, ты принял благодать подавать исцеления верующим и неверующим, приходящим к тебе, праведный Симеон. Потому, по данному тебе дару, испроси у Христа Бога исцеление нам, болеющим душевными страстями, и моли о спасении наших душ."},
  {"id": "ru-mol-0385", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0386", "section": "service", "who": "rubric", "text": "Мира суетнаго отверглся еси,/ да блага вечныя жизни наследиши,/ возлюбив незлобие и чистоту души и тела./ Снискал еси, еже возлюбил,/ свидетельствуют бо о сем гроб и нетление мощей твоих,/ и благодать чудотворения наипаче./ Точиши бо цельбы всем притекающим к тебе и непросвещенным,/ Симеоне блаженне,// чудотворче предивный."},
  {"id": "ru-mol-0387", "section": "service", "who": "reader", "text": "Покинув суетный мир, чтобы наследовать блага вечной жизни, возлюбив доброту и чистоту души и тела, ты получил то, что полюбил, ибо свидетельствуют об этом гроб и нетленные мощи твои, и более всего — благодать чудотворения, поскольку ты источаешь исцеления всем приходящим к тебе и еще не просвещенным (светом Евангелия), Симеон блаженный, удивительный чудотворец."},
  {"id": "ru-mol-0388", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0389", "section": "service", "who": "rubric", "text": "О святый и праведный Симеоне, чистою душою твоею в Небесных обителех в лице святых водворяяйся, на земли же с нами неотступно пребываяй!"},
  {"id": "ru-mol-0390", "section": "service", "who": "reader", "text": "О святой и праведный Симеон, чистой своей душой в Небесных обителях в сонме святых живёшь, на земле же с нами неотступно пребываешь!"},
  {"id": "ru-mol-0391", "section": "service", "who": "reader", "text": "По данной тебе благодати от Господа молиться о нас, милостиво обрати своё внимание на нас, многогрешных, хотя мы и недостойны, но с верой и упованием к тебе прибегающих, испроси нам от Бога прощение согрешений наших, в которые впадаем многократно во все дни нашей жизни."},
  {"id": "ru-mol-0392", "section": "service", "who": "reader", "text": "И как прежде некоторым, от сильных глазных болезней не видящим ничего, исцеление глаз, иным же, находящимся при смерти, от тяжёлых недугов врачевание и иным множество других преславных благодеяний даровал, так избавь и нас от недугов душевных и телесных и от всякой скорби и печали и всё благое для настоящей жизни нашей и для вечного спасения необходимое нам от Господа испроси, да так твоим предстательством и молитвами приобретём всё нам полезное, хотя и недостойны, с благодарностью восхваляем тебя, прославляя Бога, дивного во святых Своих, Отца и Сына и Святого Духа, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0393", "section": "service", "who": "rubric", "text": "Увечье и боль рук"},
  {"id": "ru-mol-0394", "section": "service", "who": "rubric", "text": "^ Преподобному Иоанну Дамаскину"},
  {"id": "ru-mol-0395", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:"},
  {"id": "ru-mol-0396", "section": "service", "who": "rubric", "text": "В тебе, отче, известно спасеся, еже по образу:/ приим бо крест, последовал еси Христу,/ и дея учил еси презирати убо плоть, преходит бо,/ прилежати же о души, вещи безсмертней.// Темже и со ангелы срадуется, преподобне Иоанне, дух твой."},
  {"id": "ru-mol-0397", "section": "service", "who": "reader", "text": "В тебе, отче, точно сохранилось то, что в нас по Божию образу: ибо, взяв свой крест, ты последовал за Христом, и делом учил пренебрегать плотью, как преходящей, заботиться же о душе, творении бессмертном. Потому и радуется с Ангелами, преподобный Иоанн, дух твой."},
  {"id": "ru-mol-0398", "section": "service", "who": "rubric", "text": "Тропарь иной, глас 8-й:"},
  {"id": "ru-mol-0399", "section": "service", "who": "rubric", "text": "Православия наставниче,/ благочестия учителю и чистоты,/ вселенныя светильниче,/ монашествующих Богодохновенное удобрение, Иоанне премудре,/ ученьми твоими вся просветил еси, цевнице духовная,// моли Христа Бога спастися душам нашим."},
  {"id": "ru-mol-0400", "section": "service", "who": "reader", "text": "Православия наставник, благочестия учитель и чистоты, светильник вселенной, монашествующих Богодухновенное украшение, Иоанн премудрый, учениями твоими ты всех просветил, лира духовная; моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0401", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:32"},
  {"id": "ru-mol-0402", "section": "service", "who": "rubric", "text": "Песнописца и честнаго Богоглагольника,/ Церкве наказателя и учителя,/ и врагов сопротивоборца, Иоанна воспоим:/ оружие бо взем, Крест Господень,/ всю отрази ересей прелесть,/ и яко теплый предстатель к Богу,// всем подает прегрешений прощение."},
  {"id": "ru-mol-0403", "section": "service", "who": "reader", "text": "Песнописца и почитаемого проповедника Божия, Церкви наставника и учителя, врагов противоборца, Иоанна воспоем, ибо взяв оружие, Крест Господень, отразил все заблуждения ересей и, как горячий ходатай перед Богом, всем подает прегрешений прощение."},
  {"id": "ru-mol-0404", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0405", "section": "service", "who": "rubric", "text": "Преподобне отче Иоанне! Воззри на нас милостивно и к земли приверженных возведи к высоте небесней. Ты горе на небеси, мы на земли низу, удалены от тебе, не толико местом, елико грехми своими и беззаконии, но к тебе прибегаем и взываем: настави нас ходити путем твоим, вразуми и руководствуй."},
  {"id": "ru-mol-0406", "section": "service", "who": "reader", "text": "Преподобный отец Иоанн! Посмотри милостиво на нас и к земле привязанных подними до небесной высоты. Ты высоко на небе, мы на земле внизу, удалены от тебя, не столько местом, сколько своими грехами и беззакониями, но к тебе прибегаем и взываем: наставь нас идти твоим путём, вразуми и руководи."},
  {"id": "ru-mol-0407", "section": "service", "who": "reader", "text": "Вся твоя святая жизнь была зеркалом каждой добродетели. Не переставай, угодник Божий, о нас взывать ко Господу. Испроси предстательством своим у Всемилостивого Бога нашего мир Церкви Его, под знамением Креста воинствующей, согласие и единомыслие в вере, суемудрия же и расколов истребление, утверждение во благих делах, больным исцеление, печальным утешение, обиженным заступничество, бедствующим помощь. Не посрами нас, к тебе с верой прибегающих."},
  {"id": "ru-mol-0408", "section": "service", "who": "reader", "text": "Все православные христиане твоими чудесами наполнены и милостями облагодетельствованы, исповедуют тебя своим покровителем и заступником. Показал давние свои милости, которыми ты помогал всем отцам, не отвергни и нас, их детей, идущих к тебе по их стопам. Предстоя всечестной твоей иконе, к тебе, как к живому, припадаем и молимся: прими наши молитвы и вознеси их на жертвенник Божьего милосердия, да примем с тобой благодать и необходимую помощь во временных в наших нуждах. Укрепи наше малодушие и утверди нас в вере, да несомненно уповаем получить всё благое от благосердия Владыки твоими молитвами."},
  {"id": "ru-mol-0409", "section": "service", "who": "reader", "text": "О превеликий угодник Божий! Всем нам, с верой прибегающим к тебе, помоги твоим предстательством ко Господу, и всех нас направь в мире и покаянии окончить жизнь нашу и с упованием поселиться в блаженных недрах Авраама, где ты радостно после трудов и подвигов ныне почиваешь, прославляя со всеми святыми Бога, в Троице прославляемого, Отца и Сына и Святого Духа, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0410", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Троеручица»"},
  {"id": "ru-mol-0411", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "ru-mol-0412", "section": "service", "who": "rubric", "text": "Днесь всемирная радость возсия нам велия:/ даровася святей Горе Афонстей/ цельбоносная Твоя, Владычице Богородице, икона,/ со изображением тричисленно и нераздельно пречистых рук Твоих,/ в прославление Святыя Троицы,/ созываеши бо верных и молящихся Тебе о сем познати,/ яко двема Сына и Господа держиши,/ третию же яви на прибежище и покров чтущих Тя,/ от всяких напастей и бед избавляти,/ да вси, притекающии к Тебе верою приемлют неоскудно от всех зол свобождение,/ от врагов защищение,/ сего ради и мы вкупе с Афоном вопием:// радуйся, Благодатная, Господь с Тобою."},
  {"id": "ru-mol-0413", "section": "service", "who": "reader", "text": "Сегодня нам воссияла великая всемирная радость: даровалась святой горе Афонской подающая исцеления Твоя, Владычица Богородица, икона, с изображением тройственно и нераздельно пречистых рук Твоих в прославление Святой Троицы, ибо Ты созываешь верующих и молящихся Тебе узнать об этом, так как двумя (руками) Сына и Господа держишь, третью же явила для помощи и покровительства почитающим Тебя, для избавления от всяких напастей и бед, чтобы все, приходящие к Тебе, с верой принимали неистощимо освобождение от всех зол и защиту от врагов, потому и мы вместе с Афоном взываем: «Радуйся, Благодатная, Господь с Тобой»."},
  {"id": "ru-mol-0414", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:33"},
  {"id": "ru-mol-0415", "section": "service", "who": "rubric", "text": "Днесь веселое наста ныне Твое торжество, Богомати Пречистая,/ вси вернии исполнишася радости и веселия,/ яко сподобльшеся изрядно воспети/ предивное явление честнаго образа Твоего/ и рождшагося из Тебе Младенца, истинна же Бога,/ Егоже двема рукама объемлеши,/ и третиею от напастей и бед нас изымаеши,// и избавляеши от всех зол и обстояний."},
  {"id": "ru-mol-0416", "section": "service", "who": "reader", "text": "Сегодня настало радостное Твое торжество, Пречистая Богоматерь, все верующие наполнились радостью и весельем, удостоившись особо воспевать предивное явление почитаемого образа Твоего и родившегося от Тебя Младенца, истинного Бога, Его же двумя руками Ты обнимаешь, а третью от напастей и бед нас вызволяешь и избавляешь от всех зол и невзгод."},
  {"id": "ru-mol-0417", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0418", "section": "service", "who": "rubric", "text": "О Пресвятая Госпоже Владычице Богородице, велие чудо святому Иоанну Дамаскину явившая, яко веру истинную – надежду несумненную показавшему! Услыши нас, грешных, пред чудотворною Твоею иконою усердно молящихся и просящих Твоея помощи: не отрини моления сего многих ради прегрешений наших, но, яко Мати милосердия и щедрот, избави нас от болезней, скорбей и печалей, прости содеянныя нами грехи, исполни радости и веселия всех, чтущих святую икону Твою, да радостно воспоем и любовию прославим имя Твое, яко Ты еси от всех родов избранная и благословенная во веки веков. Аминь."},
  {"id": "ru-mol-0419", "section": "service", "who": "reader", "text": "О Пресвятая Госпожа Владычица Богородица, великое чудо святому Иоанну Дамаскину показавшая, потому что он истинную веру – искренней надеждой показал! Услышь нас, грешных, пред чудотворной Твоей иконой усердно молящихся и просящих Твоей помощи: не отвергни этой молитвы из-за многих наших прегрешений, но, как Матерь милосердия и милости, избавь нас от болезней, скорбей и печалей, прости наши содеянные грехи, наполни радостью и весельем всех, почитающих святую икону Твою, да радостно воспоём и любовью прославим имя Твоё, потому что Ты — избранная от всех родов и благословенная во веки веков. Аминь."},
  {"id": "ru-mol-0420", "section": "service", "who": "rubric", "text": "Горячка, лихорадка, жар"},
  {"id": "ru-mol-0421", "section": "service", "who": "rubric", "text": "^ Первоверховному апостолу Петру"},
  {"id": "ru-mol-0422", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:34"},
  {"id": "ru-mol-0423", "section": "service", "who": "rubric", "text": "Апостолов первопрестольницы/ и вселенныя учителие,/ Владыку всех молите/ мир вселенней даровати// и душам нашим велию милость."},
  {"id": "ru-mol-0424", "section": "service", "who": "reader", "text": "Первенствующие из Апостолов и вселенские учителя, Владыку всего молите мир вселенной даровать и душам нашим великую милость."},
  {"id": "ru-mol-0425", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:35"},
  {"id": "ru-mol-0426", "section": "service", "who": "rubric", "text": "Твердыя и боговещанныя проповедатели,/ верх апостолов Твоих, Господи,/ приял еси в наслаждение благих Твоих и покой:/ болезни бо онех и смерть приял еси паче всякаго всеплодия,// Едине, сведый сердечная."},
  {"id": "ru-mol-0427", "section": "service", "who": "reader", "text": "Непоколебимых и Богогласных проповедников, высших из учеников Твоих, Господи, Ты принял в наслаждение благ Твоих и покой; ибо труды их и смерть признал Ты высшими всякой жертвы, Один, знающий то, что в сердцах."},
  {"id": "ru-mol-0428", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0429", "section": "service", "who": "rubric", "text": "О святый Петре, великий апостоле, самовидче и сотаинниче Божий, всемощною десницею Учителя твоего приятый из вод волнующихся и крайняго потопления свобождшийся!"},
  {"id": "ru-mol-0430", "section": "service", "who": "reader", "text": "О святой Пётр, великий апостол, очевидец и хранитель тайны Божией, самой сильной десницей Учителя твоего поднятый из волнующейся воды и спасённый от утопления!"},
  {"id": "ru-mol-0431", "section": "service", "who": "reader", "text": "Не забудь и нас убогих, погрязших в тине греха и охваченных волнами житейского моря: подай нам твою сильную руку, помоги нам и удержи нас от потопления в страстях, похотях, во лжи и клевете. Сделай и ты с нами милость, явленную тебе от Господа, да не в сомнении и маловерии погибнем."},
  {"id": "ru-mol-0432", "section": "service", "who": "reader", "text": "Научи нас, наш учитель, проливать слёзы покаяния, да восплачем горько о наших деяниях в этой жизни. И если твои слёзы, пролитые в покаянии, милостью Своею покрыл Господь и твой Учитель, испроси и нам, с дерзновением апостольским, прощения грехов, которые совершаем ежечасно."},
  {"id": "ru-mol-0433", "section": "service", "who": "reader", "text": "Этот город, припавший к твоим святым стопам, сохрани и огради от приключающихся лукавых козней врага нашего спасения; подними твои преподобные руки ко Господу за народ наш, да спокойную и безмятежную жизнь поживём в этом веке до часа, в который нас призовёт Владыка Господь, наш нелицеприятный Судья."},
  {"id": "ru-mol-0434", "section": "service", "who": "reader", "text": "Ты же, о всеми хвалимый апостол, не отвергнись нашего вопля и стенания к тебе, но заступись за нас пред Христом, твоим Учителем, да непрестанно славим Его милосердие к нам, со Отцом и Святым Духом, во веки веков. Аминь."},
  {"id": "ru-mol-0435", "section": "service", "who": "rubric", "text": "Женские немощи"},
  {"id": "ru-mol-0436", "section": "service", "who": "rubric", "text": "^ Священномученику Ипатию, епископу Гангрскому"},
  {"id": "ru-mol-0437", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:36"},
  {"id": "ru-mol-0438", "section": "service", "who": "rubric", "text": "Изволением Божественнаго разума/ вперив ум свой в Небесныя обители/ и равно Ангелом житие пожив на земли,/ сего ради мучения красоты венец на своем версе утвердив,/ священномучениче Ипатие,/ моли Христа Бога// спастися душам нашим."},
  {"id": "ru-mol-0439", "section": "service", "who": "reader", "text": "По воле Божественного разума устремив свой ум в Небесные обители и прожив земную жизнь, подобную Ангельской, потому и венец сладости мученичества на главу свою получив, священномученик Ипатий, моли Христа Бога о спасении душ наших."},
  {"id": "ru-mol-0440", "section": "service", "who": "rubric", "text": "Другой тропарь, глас 3-й:"},
  {"id": "ru-mol-0441", "section": "service", "who": "rubric", "text": "В прекрасном Церкве апостольския вертограде/ из юна возраста всесильною десницею Божиею насадился еси,/ Богоблаженне отче Ипатие,/ и в ней, яко верен первосвященник,/ верно Богоначальное и Всетворящее Троическое Единство/ проповедал еси во Вселенском Собрании,/ Духа же Святаго в добродетелех исполнен быв,/ велия чудеса сотворив,/ мучением за веру Христову скончався,/ пришел еси в Небесный град,/ идеже Триипостасного Бога зря,/ моли о чествующих тя,// да в Горнем Иерусалиме со святыми жити сподобимся."},
  {"id": "ru-mol-0442", "section": "service", "who": "reader", "text": "В прекрасном винограднике апостольской Церкви/ от юного возраста самой сильной десницей Божьей был посажен,/ Богоблаженный отче Ипатий,/ и в нём, как истинный первосвященник,/ с верой в Богоначальное и Всетворящее Троическое Единство/ ты проповедал на Вселенских Соборах,/ Святого Духа же в добродетелях был наполнен,/ великие чудеса сотворивший,/ мучением за веру во Христа жизнь окончивший,/ пришёл в Небесный град,/ где Триипостасного Бога созерцая,/ моли о чествующих тебя,// да в Небесном Иерусалиме со святыми сподобимся жить."},
  {"id": "ru-mol-0443", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0444", "section": "service", "who": "rubric", "text": "Римскому отечеству светильник,/ Богозарными лучами концы светя,/ ныне просвети твое празднество поющия, Ипатие,/ прося свыше мира и грехов оставления,// молитвами защити ны, Ипатие многострадальне."},
  {"id": "ru-mol-0445", "section": "service", "who": "reader", "text": "Римскому государству светильник, просвещая концы Земли лучами Небесного света, сейчас просвети воспевающих твою память, Ипатий, прося свыше мир и прощение грехов, молитвами защити нас, Ипатий, много пострадавший."},
  {"id": "ru-mol-0446", "section": "service", "who": "rubric", "text": "Другой кондак, глас 2-й:"},
  {"id": "ru-mol-0447", "section": "service", "who": "rubric", "text": "Обитель Триипостаснаго Божества,/ достоблаженне отче Ипатие, быв,/ во вселенную Всетворца Бога воскликнул еси./ Благодарственне же чудодействуя,/ вшел еси в Небесныя обители,/ тамо моли Всесвятую Троицу, молим тя,/ исцелити телеса и души наша// в Богосозданную нашу красоту."},
  {"id": "ru-mol-0448", "section": "service", "who": "reader", "text": "Обителью Триипостасного Бога, достойный блаженств отче Ипатий, был ты, Всетворца Бога прославив во всей вселенной. Совершая же чудеса, вошел ты в Небесные обители, где моли Всесвятую Троицу, молим тебя, исцелить тела и души наши, вернув их к Богосозданной красоте."},
  {"id": "ru-mol-0449", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0450", "section": "service", "who": "rubric", "text": "Трисолнечного Света светозарная звездо, вводящая в мир Трисолнечный Свет апостольскими твоими, Богоевангельскаго проповедания священноучении, священномучениче, иерарше Христов, Богоблаженне Ипатие."},
  {"id": "ru-mol-0451", "section": "service", "who": "reader", "text": "Трисолнечного Света ярчайшая звезда, вводящая в мир Трисолнечный Свет апостольскими твоими проповедями святые учения о Боге и Евангелии, священномученик, иерарх Христов, Богоблаженный Ипатий."},
  {"id": "ru-mol-0452", "section": "service", "who": "reader", "text": "Ты принял от Святой Троицы благодать, равную апостольской, и к Богу любовь, в горячности равной серафимской, подобно верховнейшему из апостолов Петру, и премудрость в учении, как у многоглазых херувимов, как второй Павел. Просветивший премудрым твоим учением благочестия множество народов, всегда усердно подражал всемирному Учителю, Господу Богу и Спасителю нашему Иисусу Христу."},
  {"id": "ru-mol-0453", "section": "service", "who": "reader", "text": "Потому смиренно молю твою отцовскую, подражательную Божественной, милость: обрати своё милостивое внимание богосветлыми твоими глазами на моё недостоинство, как любящий всех детей после Бога отец, и всегда усердный наставник в нашем спасении, и всех в Небесных правильный и неизменный управитель, самая твёрдая стена Православию и пресветлый столп, вводящий второй и новый Израиль в светлейший Небесный Сион."},
  {"id": "ru-mol-0454", "section": "service", "who": "reader", "text": "Поспеши вскоре помочь в битве нашему войску. Проси всегда у Святой Троицы всем православным христианам мира и тишины, душевного спасения и многолетнего телесного здоровья, благоприятную погоду, изобилие земных плодов, бездетным изобилие детей и в законе Господнем воспитание, и всех благ умножение."},
  {"id": "ru-mol-0455", "section": "service", "who": "reader", "text": "А после этой жизни каждого сподоби святыми твоими молитвами получить благую христианскую кончину, непостыдную и мирную, с самым преподобным исповеданием и с причастием Святых Бессмертных Небесных и Животворящих Тайн Христа, и с елеосвящением беспрепятственно пройдя воздушные мытарства, унаследовать со святыми всегда радостную вечную жизнь, в которой вместе с Ангельскими чинами непрестанную хвалу вознесём Отцу с Единородным Его Сыном и с Пресвятым, Благим и Животворящим Его Духом, и тебе, прославляя великую твою отеческую милостивую защиту, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0456", "section": "service", "who": "rubric", "text": "Проказа"},
  {"id": "ru-mol-0457", "section": "service", "who": "rubric", "text": "^ Преподобному Антонию Великому"},
  {"id": "ru-mol-0458", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "ru-mol-0459", "section": "service", "who": "rubric", "text": "Ревнителя Илию нравы подражая,/ Крестителю правыми стезями последуя,/ отче Антоние,/ пустыни был еси житель,/ и вселенную утвердил еси молитвами твоими./ Темже моли Христа Бога,// спастися душам нашим."},
  {"id": "ru-mol-0460", "section": "service", "who": "reader", "text": "Ревнителю Илии нравом подражая, за Крестителем прямыми путями следуя, отче Антоний, ты сделался обитателем пустыни и вселенную утвердил молитвами твоими. Потому ходатайствуй пред Христом Богом о спасении душ наших."},
  {"id": "ru-mol-0461", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:37"},
  {"id": "ru-mol-0462", "section": "service", "who": "rubric", "text": "Житейския молвы отринув,/ безмолвно житие скончал еси,/ Крестителя подражаяй всяким образом преподобнейший,/ с ним убо тя почитаем,// отцев начальниче Антоние."},
  {"id": "ru-mol-0463", "section": "service", "who": "reader", "text": "Житейские волнения отринув, безмятежно жизнь ты завершил, Крестителю всячески подражая, преподобнейший! С ним тебя и почитаем, отче отцов Антоний!"},
  {"id": "ru-mol-0464", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0465", "section": "service", "who": "rubric", "text": "О великий угодниче Божий, преподобне отче Антоние! Яко имея дерзновение ко Владыце Христу и ко Пречистей Его Матери, буди о нас, недостойных, молитвенник теплый, заступая нас от всяких бед и напастей, да твоими молитвами невредимы от враг видимых и невидимых пребудем. Моли милосердие Божие, да спасет нас от прегрешений наших имиже веси судьбами."},
  {"id": "ru-mol-0466", "section": "service", "who": "reader", "text": "О великий угодник Божий, преподобный отче Антоний! Поскольку имеешь дерзновение ко Владыке Христу и к Пречистой Его Матери, будь о нас, недостойных, усердный молитвенник, защищая нас от всяких бед и напастей, да твоими молитвами невредимыми отврагов видимых и невидимых будем."},
  {"id": "ru-mol-0467", "section": "service", "who": "reader", "text": "Моли Божие милосердие, да спасёт нас от прегрешений наших известными ему судьбами. Моли Его благость, чтобы с милостью даровал этому храму (дому) необходимое, чтобы примирил нашу жизнь и всех прихожан этого храма помиловал и спас наши души, да всегда славим, хвалим, поём и величаем Пречестное и Славное имя Отца и Сына и Святого Духа, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0468", "section": "service", "who": "rubric", "text": "Бессонница"},
  {"id": "ru-mol-0469", "section": "service", "who": "rubric", "text": "^ Святым седми отрокам, иже во Ефесе: Максимилиану, Иамвлиху, Мартиниану, Иоанну, Дионисию, Ексакустодиану и Антонину"},
  {"id": "ru-mol-0470", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:38"},
  {"id": "ru-mol-0471", "section": "service", "who": "rubric", "text": "Благочестия проповедники и Воскресения умерших изобразители,/ Церкви столпы седмочисленныя,/ отроки всеблаженныя песньми восхвалим:/ тии бо по многих летех нетления, аки от сна воставше,// всем возвестиша яве мертвых востание."},
  {"id": "ru-mol-0472", "section": "service", "who": "reader", "text": "Благочестия проповедников, образ Воскресения умерших собой представивших, семь столпов Церкви, отроков всеблаженных в молитвенных песнопениях прославим, ибо они после многих лет нетления, как ото сна восстав, всем возвестили ясно воскресение мертвых."},
  {"id": "ru-mol-0473", "section": "service", "who": "rubric", "text": "Кондак, глас 4-й:"},
  {"id": "ru-mol-0474", "section": "service", "who": "rubric", "text": "Прославивый на земли святыя Твоя/ прежде втораго и страшнаго пришествия Твоего, Христе,/ преславным востанием отроков/ показал еси Воскресение неведящим е,/ нетленна одеяния и телеса явив,/ и царя уверил еси вопити:// воистинну есть мертвых востание."},
  {"id": "ru-mol-0475", "section": "service", "who": "reader", "text": "Прославивший на земле святых Твоих прежде Второго и страшного Пришествия Твоего, Христос, невероятным воскресением отроков показал Воскресение не знающим о нем, явив нетленные одежды и тела, и царя укрепил в вере, взывать: «Истинно есть воскресение мертвых!»"},
  {"id": "ru-mol-0476", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0477", "section": "service", "who": "rubric", "text": "О пречуднии святии седмичисленнии отроцы, Ефеса града похвало и всея вселенныя упование! Воззрите с высоты Небесныя славы на ны, любовию память вашу чтущия, наипаче же на младенцы христианския, вашему заступлению от родителей своих препорученныя."},
  {"id": "ru-mol-0478", "section": "service", "who": "reader", "text": "О пречудные святые семь отроков, похвала города Ефеса и всей вселенной упование! Посмотрите с высоты Небесной славы на нас, почитающих с любовью вашу память, а более всего на христианских младенцев, порученных своими родителями вашему заступничеству."},
  {"id": "ru-mol-0479", "section": "service", "who": "reader", "text": "Ниспошлите на них благословение Христа Бога, сказавшего: пустите детей приходить ко Мне (Мф. 19:14). Болеющих из них исцелите, скорбящих утешьте, сердца их сохраните в чистоте, наполните их кротостью и в землю сердец их зерно Божьего исповедания насадите и укрепите, чтобы от силы в силу им возрастать."},
  {"id": "ru-mol-0480", "section": "service", "who": "reader", "text": "И всех нас, перед святой иконой вашей предстоящих и любызающих с верой ваши мощи и с усердием к вам молящихся, сподобите Царство Небесное получить и неумолкающими голосами радости там прославлять славное Имя Пресвятой Троицы, Отца и Сына и Святого Духа, во веки веков. Аминь."},
  {"id": "ru-mol-0481", "section": "service", "who": "rubric", "text": "^ Святому преподобному Иринарху, затворнику Ростовскому"},
  {"id": "ru-mol-0482", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:39"},
  {"id": "ru-mol-0483", "section": "service", "who": "rubric", "text": "Яко мученика добропроизвольна/ и преподобных удобрение,/ звезду Ростовскую,/ в затворе, узах и веригах Господеви благоугодившаго/ и чудес благодать от Него приемшаго,/ Иринарха предивнаго песньми хвалебными почтим/ и, к нему припадающе, умильно глаголем:/ отче преподобне, моли Христа Бога// спастися душам нашим."},
  {"id": "ru-mol-0484", "section": "service", "who": "reader", "text": "Как мученика добровольного и преподобных украшение, звезду Ростовскую, в затворе, цепях и веригах Господу угодившего и чудес благодать от Него получившего, Иринарха удивительного в хвалебных песнопениях почтим и коленопреклоненно в сокрушении к нему воззовем: «Отче преподобный, моли Христа Бога о спасении душ наших»."},
  {"id": "ru-mol-0485", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0486", "section": "service", "who": "rubric", "text": "Волнений множество жестоким житием преходя,/ изгнание, затвор и узы железныя претерпел еси мужески, Иринарше терпеливодушне,/ нам оставль образ злострадания и терпения твоего,/ озаряя чудес блистаньми с верою приходящих к честному гробу твоему,/ у негоже, яко почесть победную, вериги твоя тяжкие видим,/ от нихже подаеши исцеления недужным./ Сего ради зовем ти:// радуйся, Иринарше, отче предивный."},
  {"id": "ru-mol-0487", "section": "service", "who": "reader", "text": "Сквозь многие бури в суровой жизни проходя, изгнание, затвор и железные цепи претерпел ты мужественно, твердый душой Иринарх, оставив нам пример твоих мучений и терпения, озаряя сиянием чудес с верой приходящих к почитаемому гробу твоему, у него же, как награду победы, вериги твои тяжелые видим, от них же подаешь исцеления больным. Потому взываем к тебе: «Радуйся, Иринарх, отче удивительный»."},
  {"id": "ru-mol-0488", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0489", "section": "service", "who": "rubric", "text": "О преподобне отче Иринарше! Се мы молим тя усердно: буди ходатай наш присный, испроси нам от Христа Бога мир, тишину, благоденствие, здравие и спасение, и от всех врагов видимых и невидимых ограждение, покрый же нас ходатайством твоим от нахождения всяких бед и скорбей, паче же от искушения врага темнаго, да вси мы с тобою прославляем всесвятое имя Отца и Сына и Святаго Духа, ныне и присно и во веки веков. Аминь."},
  {"id": "ru-mol-0490", "section": "service", "who": "reader", "text": "О преподобный отче Иринарх! Мы усердно молим тебя: будь постоянным нашим посредником, испроси нам у Христа Бога мир, спокойствие, благоденствие, здоровье и спасение, и от всех врагов, видимых и невидимых, ограждение, покрой нас твоим ходатайством от нашествия всяких бед и скорбей, более всего от искушений тёмного врага, да все мы с тобой прославляем всесвятое имя Отца и Сына и Святого Духа, ныне и всегда и во веки веков. Аминь."},
  {"id": "ru-mol-0491", "section": "service", "who": "rubric", "text": "Паралич"},
  {"id": "ru-mol-0492", "section": "service", "who": "rubric", "text": "^ Преподобному Иакову, игумену Железноборовскому"},
  {"id": "ru-mol-0493", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:40"},
  {"id": "ru-mol-0494", "section": "service", "who": "rubric", "text": "Небеснаго желая,/ земная возненавидел еси/ и, взем крест свой, последовал еси Христу/ и от Него прием дарования чудес,/ исцеляти недужныя;/ но, яко имея дерзновение ко Святей Троице,/ испроси православным христианом здравие и спасение,/ на враги же победу/ и не забуди, посещая чад своих,/ припадающих к цельбоносному гробу твоему,// Иакове, преподобне отче наш."},
  {"id": "ru-mol-0495", "section": "service", "who": "reader", "text": "Желая Небесного, ты отвратился от всего земного и, взяв крест свой, последовал за Христом и от Него принял дар чудотворений, исцеления больных. Но, как имеющий право обращаться ко Святой Троице, испроси для православных христиан здоровье и спасение, победу над врагами и не оставь детей своих, обращая внимание на всех, припадающих к подающему исцеления гробу твоему, Иаков, преподобный отче наш."},
  {"id": "ru-mol-0496", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0497", "section": "service", "who": "rubric", "text": "Сердечная очи, досточудне, ко Господу вперив/ и телесныя страсти из корене исторгая,/ неболезненную жизнь в болезнех восприял еси, преподобне,/ болезнем же лютым даеши исцеление просящим с верою у тебе,/ темже молим тя, досточудне,/ исцели наша болезни душевныя и телесныя, да зовем ти:// радуйся, Иакове Богомудре, отче наш."},
  {"id": "ru-mol-0498", "section": "service", "who": "reader", "text": "Очи сердечные, достойный удивления, устремив ко Господу и с корнем исторгая телесные страсти ты провел безболезненную жизнь в болезнях, преподобный, просящим у тебя с верой даешь исцеление мучительных болезней, потому молим тебя, достойный удивления, исцели наши болезни душевные и телесные, да взываем к тебе: «Радуйся, Иаков, умудренный Богом, отче наш»."},
  {"id": "ru-mol-0499", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0500", "section": "service", "who": "rubric", "text": "Преподобне и богоносне отче наш Иакове! Приими ныне нас, тебе усердно молящихся и припадающих ко всечестному и многоцелебному твоему гробу, идеже святое твое и многотрудное покоится тело. Духом же на Небесех предстоя Святей Троицы со Ангелы и преподобных отцев лики, молися о нас, чадех твоих, отче, да избавимся от всяких скорбей, болезней, бед и обстояний, и благочестно поживем в настоящем житии, ходяще в заповедех и оправданиих Господних безпорочно, и да явимся последователи святому и равноангельскому житию твоему."},
  {"id": "ru-mol-0501", "section": "service", "who": "reader", "text": "Преподобный и богоносный отче наш Иаков! Прими ныне нас, к тебе усердно молящихся и припадающих ко всеми почитаемому и подающему многие исцеления твоему гробу, где твоё святое твое и претерпевшее многие труды покоится тело. Духом же на Небе предстоящий Святой Троице с Ангелами и с сонмом преподобных отцов, молись о нас, твоих чадах, отче, да избавимся от всяких скорбей, болезней, бед и невзгод, и проведём нынешнюю жизнь в благочестии, ходя беспорочно в заповедях и установлениях Господа, и да станем последователями святой и равной Ангелам твоей жизни."},
  {"id": "ru-mol-0502", "section": "service", "who": "reader", "text": "О преподобный отче, молим тебя, испроси нам и всем, с верой к тебе прибегающим, прощение грехов, здоровье тела, исправление жизни и вечное спасение, да твоим предстательством спасение и славу сподобимся воссылать в Троице славимому Богу, Отцу, и Сыну, и Святому Духу, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0503", "section": "service", "who": "rubric", "text": "Болезни крови"},
  {"id": "ru-mol-0504", "section": "service", "who": "rubric", "text": "^ Мученику Иоанну воину, чудотворцу"},
  {"id": "ru-mol-0505", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:41"},
  {"id": "ru-mol-0506", "section": "service", "who": "rubric", "text": "Блаженство евангельское возлюбив, Богомудре Иоанне,/ чистоту сердца девством почтил еси./ Темже суету мира сего пренебрег,/ устремился еси зрети Бога,/ Иже тя прослави чудесы во врачевании различне страждущих./ Сего ради молим тя:/ проси нам у Христа Господа всяких скорбей избавления// и получения Царства Небеснаго."},
  {"id": "ru-mol-0507", "section": "service", "who": "reader", "text": "Блаженство евангельское возлюбив, Богомудрый Иоанн, ты прославил чистоту своего сердца девством. Потому суету мира этого отверг, устремившись к созерцанию Бога, Который тебя прославил чудесами во врачевании различных страдающих. Поэтому молим тебя: «Испроси нам у Христа Господа избавление от всяких скорбей и получение Царства Небесного»."},
  {"id": "ru-mol-0508", "section": "service", "who": "rubric", "text": "Кондак, глас 6-й:"},
  {"id": "ru-mol-0509", "section": "service", "who": "rubric", "text": "Благочестиваго воина Христова,/ победившаго враги душевныя и телесныя богомудренно,/ Иоанна мученика достодолжно песньми восхвалим,/ чудодействуя бо, подает обильная исцеления страждущим людем/ и молится Господу Богу// от всяких бед спасти правоверныя."},
  {"id": "ru-mol-0510", "section": "service", "who": "reader", "text": "Благочестивого воина Христова, победившего врагов душевных и телесных Богомудро, Иоанна мученика по достоинству молитвенными песнопениями прославим, ибо он, совершая чудеса, подает обильные исцеления страдающим людям и молится Господу Богу о спасении православных от всяких бед."},
  {"id": "ru-mol-0511", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0512", "section": "service", "who": "rubric", "text": "О великий Христов мучениче Иоанне, правоверных поборниче, врагов прогонителю и обидимых заступниче! Услыши нас, в бедах и скорбях молящихся тебе, яко дана тебе бысть благодать от Бога печальныя утешати, немощным помогати, неповинныя от напрасныя смерти избавляти и за всех зле страждущих молитися."},
  {"id": "ru-mol-0513", "section": "service", "who": "reader", "text": "О великий мученик Христов Иоанн, благочестивых защитник, врагов прогонитель и обиженных заступник! Услышь нас, в бедах и скорбях к тебе молящихся, потому что дана тебе благодать от Бога утешать печальных, помогать немощным, неповинных от внезапной смерти избавлять и за всех страдающих молиться."},
  {"id": "ru-mol-0514", "section": "service", "who": "reader", "text": "Поэтому будь и нам сильным защитником от всех видимых и невидимых врагов наших, потому что с твоей помощью и защитой посрамятся все делающие нам злое. Умоли Господа нашего, да сподобит нас грешных и недостойных рабов Своих получить от Него несказанные блага, которые Он приготовил любящим Его, в Троице Святой прославляемого Бога, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0515", "section": "service", "who": "rubric", "text": "Нарывы"},
  {"id": "ru-mol-0516", "section": "service", "who": "rubric", "text": "^ Святым чудотворцам и бессребреникам, мученикам Киру и Иоанну"},
  {"id": "ru-mol-0517", "section": "service", "who": "rubric", "text": "Тропарь, глас 5-й:"},
  {"id": "ru-mol-0518", "section": "service", "who": "rubric", "text": "Святии славнии Кире и Иоанне,/ бессребреницы, мученицы и чудотворцы,/ милосердием своим, яко стеною необоримою, нас оградите от всех бед/ и от врагов видимых и невидимых сохраните// непрестанною вашею молитвою ко Господу."},
  {"id": "ru-mol-0519", "section": "service", "who": "reader", "text": "Святые прославляемые Кир и Иоанн, бессеребренники, мученики и чудотворцы, милосердием своим, как стеной нерушимой, нас оградите от всех бед и от врагов видимых и невидимых сохраните постоянной молитвой вашей ко Господу."},
  {"id": "ru-mol-0520", "section": "service", "who": "rubric", "text": "Кондак, глас 3-й:"},
  {"id": "ru-mol-0521", "section": "service", "who": "rubric", "text": "От Божественныя благодати дар чудес приемше, святии,/ чудодействуете, непрестанно,/ вся наша страсти рукодейством секуще невидимым,/ Кире Богомудре со Иоанном славным:// вы бо божественнии врачеве есте."},
  {"id": "ru-mol-0522", "section": "service", "who": "reader", "text": "От Божественной благодати дар чудес приняв, святые, вы чудодействуете непрестанно, все наши страсти отсекая врачеванием невидимым, Кир Богомудрый с Иоанном славным: ибо вы – Божественные врачи."},
  {"id": "ru-mol-0523", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0524", "section": "service", "who": "rubric", "text": "О святые чудотворцы и врачи безмездные Кире и Иоанне, прибегаем к вам, от болезней наших страдая люто. Во дни жизни вашея проповедовали вы, яко недуг души тяжелее всех недугов тела и, егда душа грехами болезнует, часто и тело в болезнь впадает."},
  {"id": "ru-mol-0525", "section": "service", "who": "reader", "text": "О святые чудотворцы и врачи безвозмездные Кир и Иоанн, прибегаем к вам, люто страдающие от своих болезней. Во дни земной вашей жизни вы проповедовали, что недуг души тяжелее всех недугов тела и, когда душа больна грехами, часто и тело начинает болеть."},
  {"id": "ru-mol-0526", "section": "service", "who": "reader", "text": "Знаем мы, что болезнями очищаемся от грехов; умолите же, святые чудотворцы, Господа, да дарует Он нам прощение согрешений, слабым и беспомощным, болезнями измождённых, да не погибнем, впав в уныние. Поспешите на помощь нам и исцелите наши болезни, да мы в здравии и в покаянии наши дни проведя, в мире окончим нашу жизнь и в день Суда с чистым сердцем предстанем пред глазами Судьи вселенной, Сердцеведца Бога. Которого поём и славим во веки веков. Аминь."},
  {"id": "ru-mol-0527", "section": "service", "who": "rubric", "text": "Кожные болезни и язвы"},
  {"id": "ru-mol-0528", "section": "service", "who": "rubric", "text": "^ Праведному Артемию Веркольскому, чудотворцу"},
  {"id": "ru-mol-0529", "section": "service", "who": "rubric", "text": "Тропарь, глас 2-й:"},
  {"id": "ru-mol-0530", "section": "service", "who": "rubric", "text": "Вышняго повелением,/ тученосным облаком небо помрачившим,/ и молниям блистающим,/ грому же возшумевшу с прещением,/ испустил еси душу твою в руце Господеви,/ премудре Артемие,/ и ныне предстоиши Престолу Владыки всех,/ иже верою и любовию приходящим к тебе,/ подая исцеление всем неотложно,/ и моляся Христу Богу,// спастися душам нашим."},
  {"id": "ru-mol-0531", "section": "service", "who": "reader", "text": "По воле Всевышнего, грозовым облаком небо помрачившего, в блистании молний и угрожающем шуме грома ты отпустил душу свою в руки Господа, премудрый Артемий, и сейчас предстоишь Престолу Владыки всех, с верою и любовью приходящим к тебе подавая исцеление без отлагательств и молясь Христу Богу о спасении наших душ."},
  {"id": "ru-mol-0532", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0533", "section": "service", "who": "rubric", "text": "Возсия днесь пресветлая память премудраго Артемия;/ Богоданная благодать яко реки изливает от целебных мощей его дивная исцеления,/ имиже от многоразличных недуг избавляемся,/ с верою приемлюще я, и взывающе:// радуйся, Артемие Богомудре."},
  {"id": "ru-mol-0534", "section": "service", "who": "reader", "text": "Воссияла сегодня пресветлая память премудрого Артемия. Богоданная благодать как реки изливает от врачующих мощей его удивительные исцеления, которыми мы избавляемся от многоразличных болезней, с верой принимая их и взывая: «Радуйся, Артемий Богомудрый»."},
  {"id": "ru-mol-0535", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0536", "section": "service", "who": "rubric", "text": "Святый угодниче Божий, праведный Артемие, присный хранителю святыя веры Православныя и близкий защитниче всего севернаго края Российския страны! Призри милостивно на усердную молитву нас грешных и твоим благомощным предстательством испроси нам у Господа прощение согрешений наших, преспеяние в вере и благочестии и ограждение от козней диавольских."},
  {"id": "ru-mol-0537", "section": "service", "who": "reader", "text": "Святой угодник Божий, праведный Артемий, истинный хранитель святой Православной веры и близкий защитник всего северного края России! Обрати своё милостивое внимание на усердную молитву нас грешных и твоим твёрдым предстательством испроси нам у Господа прощение согрешений наших, преуспевание в вере и благочестии и ограждение от диавольских козней."},
  {"id": "ru-mol-0538", "section": "service", "who": "reader", "text": "Моли Господа, да сохранит в здравии и подлинном благополучии верных людей Своих, да подаст стране нашей мир и тишину, а нам нелицемерное послушание, да сподобит всех нас получить после христианской кончины Небесное Царство, где все праведные вместе с тобой, вечно славят Отца и Сына и Святого Духа. Аминь."},
  {"id": "ru-mol-0539", "section": "service", "who": "rubric", "text": "Водянка"},
  {"id": "ru-mol-0540", "section": "service", "who": "rubric", "text": "^ Преподобному Ипатию, игумену Руфианскому"},
  {"id": "ru-mol-0541", "section": "service", "who": "rubric", "text": "Тропарь, глас 8-й:"},
  {"id": "ru-mol-0542", "section": "service", "who": "rubric", "text": "В тебе, отче, известно спасеся, еже по образу:/ приим бо крест, последовал еси Христу,/ и дея учил еси презирати убо плоть, преходит бо,/ прилежати же о души, вещи безсмертней.// Темже и со Ангелы срадуется, преподобне Ипатие, дух твой."},
  {"id": "ru-mol-0543", "section": "service", "who": "reader", "text": "В тебе, отче, точно сохранилось то, что в нас по Божию образу: ибо взяв свой крест, ты последовал за Христом, и делом учил пренебрегать плотью, как преходящей, заботиться же о душе, творении бессмертном. Потому и радуется с Ангелами, преподобный Ипатий, дух твой."},
  {"id": "ru-mol-0544", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:"},
  {"id": "ru-mol-0545", "section": "service", "who": "rubric", "text": "Чистотою душевною божественне вооружився, и непрестанныя молитвы, яко копие вручив крепко, пробол еси бесовская ополчения, преподобне Ипатие, отче наш, моли непрестанно о всех нас."},
  {"id": "ru-mol-0546", "section": "service", "who": "reader", "text": "Чистотой душевной с Божией помощью вооружившись, и непрестанные молитвы, как копье взяв крепко, низложил ты бесовские ополчения, преподобный Ипатий, отче наш; моли непрестанно о всех нас."},
  {"id": "ru-mol-0547", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0548", "section": "service", "who": "rubric", "text": "Прославляется Бог в совете правых, ибо возсиял пред людьми свет добродетелей святого Ипатия, прибегая к которому, из глубины сердца взываем: инок совершенный был ты, Ипатий преподобный, многими трудами к вратам небесным очищавший себе путь."},
  {"id": "ru-mol-0549", "section": "service", "who": "reader", "text": "Прославляется Бог в сонме праведных, потому что воссиял пред людьми свет добродетелей святого Ипатия, прибегая к которому, из глубины сердца взываем: ты был совершенный инок, Ипатий преподобный, многими трудами к вратам небесным очищавший себе путь."},
  {"id": "ru-mol-0550", "section": "service", "who": "reader", "text": "В необитаемую киновию Руфима придя с учениками, ты очистил её и в прежнее благолепие привёл. Там, власяницы делая, ты совершал великие подвиги. Ты получил дар от Господа, Ипатий достойный похвалы, различные недуги исцелять, а более всего водянку."},
  {"id": "ru-mol-0551", "section": "service", "who": "reader", "text": "Обрати своё внимание на страждущих тяжёлой этой болезнью, святой Ипатий, и умилостиви твоей благоприятной молитвой Господа, и стань рядом с немощными невидимой чудодейственной силой Божьей, исцеляя их по великой милости Господней, и пусть, почувствовав облегчение в теле и бодрость духа, они отвергнут нерадение и ревностно пойдут по лестнице добродетелей, направятся на преуспеяние в богоугодных делах, и славя Отца и Сына, и Святого Духа, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0552", "section": "service", "who": "rubric", "text": "Расслабление тела, связанное с бессонницей, потерей аппетита и лишением каких-либо членов"},
  {"id": "ru-mol-0553", "section": "service", "who": "rubric", "text": "^ Преподобному Никите Столпнику, Переяславскому чудотворцу"},
  {"id": "ru-mol-0554", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "ru-mol-0555", "section": "service", "who": "rubric", "text": "Христову мученику тезоименит был еси, преподобне, / многи подвиги и труды претерпел еси Христа ради, / Егоже ради вериги носил еси, блаженне, / Того ныне о нас моли, Никито преподобне, / душевныя наша и телесныя страсти уврачевати, / иже верою и любовию // почитающих присно память твою."},
  {"id": "ru-mol-0556", "section": "service", "who": "reader", "text": "Ты был соименит мученику Христову, преподобный, / многие подвиги и труды выдержал ради Христа, / ради Которого ты носил вериги, блаженный, / Его ныне о нас моли, Никита преподобный, / излечить наши душевные и телесные страсти, / с верой и любовью // всегда почитающих твою память."},
  {"id": "ru-mol-0557", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:42"},
  {"id": "ru-mol-0558", "section": "service", "who": "rubric", "text": "Христа ради от твоих рабов нуждную смерть претерпел еси/ и венец нетления от Него восприял еси,/ приходящим же с верою от честнаго твоего гроба подаеши цельбы,/ о Никито преподобне,// молитвенниче о душах наших."},
  {"id": "ru-mol-0559", "section": "service", "who": "reader", "text": "Ради Христа ты претерпел насильственную смерть от рабов твоих и принял от Него нетленный венец, приходящим же с верой от почитаемого твоего гроба подаешь исцеления, о Никита преподобный, молитвенник о душах наших."},
  {"id": "ru-mol-0560", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0561", "section": "service", "who": "rubric", "text": "О всечестная главо, преподобне отче преблаженне, Никито преподобномучениче! Не забуди нищих твоих до конца, но поминай нас всегда во святых своих и благоприятных молитвах к Богу и не забуди присещати чад своих."},
  {"id": "ru-mol-0562", "section": "service", "who": "reader", "text": "О всечестная голова, преподобный и блаженный отче Никита преподобномученик! Не забудь нищих твоих до конца, но поминай нас всегда во святых своих и благоприятных к Богу молитвах и не забудь охранять своих чад."},
  {"id": "ru-mol-0563", "section": "service", "who": "reader", "text": "Моли за нас, отче благой и избранник Христов, потому что имеешь дерзновение к Небесному Царю, и не прекрати взывать за нас ко Господу, и не пренебреги нами, с верою и любовью чтущими тебя. Поминай нас, недостойных, у Престола Вседержителя и не переставай молиться о нас ко Христу Богу: дана тебе благодать за нас молиться."},
  {"id": "ru-mol-0564", "section": "service", "who": "reader", "text": "Мы не считаем тебя мёртвым: хотя ты и телесно переселился от нас, но и по смерти живым пребываешь. Не отступай от нас духом, сохраняя и соблюдая нас от стрел вражеских, и всякого прельщения бесовского, заступник и молитвенник наш добрый. Хотя мощей твоих рака пред очами нашими видима всегда, но святая твоя душа с ангельскими воинствами, со Бесплотными хорами, с Небесными силами, у Престола Вседержителя Бога достойно веселится."},
  {"id": "ru-mol-0565", "section": "service", "who": "reader", "text": "Зная, что ты воистину и после смерти жив, к тебе припадаем, и тебя молим, и умоляем, да помолишься о нас Всесильному Богу к пользе душ наших, и испросишь нам время на покаяние, и беспрепятственный переход от земли на Небо, и от мытарств горьких, и воздушных князей и вечной муки избавление, и да будем мы наследниками Небесного Царства со всеми праведными, от века угодившими Ему, Господу нашему Иисусу Христу. Ему подобает всякая слава, честь и поклонение со Безначальным Его Отцом, и с Пресвятым, и Благим, и Животворящим Его Духом ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0566", "section": "service", "who": "rubric", "text": "Рак"},
  {"id": "ru-mol-0567", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Всецарица» (Пантанасса)"},
  {"id": "ru-mol-0568", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:"},
  {"id": "ru-mol-0569", "section": "service", "who": "rubric", "text": "Образом радостотворным честныя Всецарицы,/ желанием теплым взыскающих благодати Твоея спаси, Владычице,/ избави от обстояний к Тебе прибегающих;/ от всякия напасти огради стадо Твое,// к заступлению Твоему взывающее присно."},
  {"id": "ru-mol-0570", "section": "service", "who": "reader", "text": "Почитаемым образом «Всецарица», дарующим радость, всех с горячим желанием ищущих Твоей благодати спаси, Владычица, и избавь от бедствий к Тебе обращающихся, от всяких напастей огради стадо Твое, к защите Твоей всегда взывающее."},
  {"id": "ru-mol-0571", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0572", "section": "service", "who": "rubric", "text": "Новоявленней Твоей иконе предстояще вернии, умильно воспеваем Ти, Всецарице, раби Твои; низпосли цельбы к Тебе притекающим ныне рабом Твоим, да вси радостно зовем Ти: Радуйся, Всецарице, недуги наша благодатию исцеляющая."},
  {"id": "ru-mol-0573", "section": "service", "who": "reader", "text": "Мы, верные, предстоя новоявленной Твоей иконе, с умилением воспеваем Тебя, о Всецарице, ниспошли рабам Твоим исцеление к Тебе ныне прибегающим, да все радостно взываем Тебе: Радуйся, Всецарица, болезни наши благодатью исцеляющая."},
  {"id": "ru-mol-0574", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0575", "section": "service", "who": "rubric", "text": "О Всеблагая, досточудная Богородице Пантанасса, Всецарице! Несмь достоин, да внидеши под кров мой, но яко милостиваго Бога любоблагоутробная Мати, рцы слово, да исцелится душа моя и укрепится немощствующее тело мое. Имаши бо державу непобедимую, и не изнеможет у Тебе всяк глагол, о Всецарице! Ты за мя упроси, Ты за мя умоли, да прославляю преславное имя Твое всегда, ныне и в безконечныя веки. Аминь."},
  {"id": "ru-mol-0576", "section": "service", "who": "reader", "text": "О Всеблагая, изумления достойная, чудная Богородица, Пантанасса, Всецарица! Я не достоин(-а), чтобы Ты вошла под кров мой, но как милостивого Бога любящая милосердие Матерь, скажи слово, да исцелится душа моя и да укрепится немощное тело мое. Потому что Ты имеешь мощь непобедимую и не останется у Тебя бессильным никакое слово, о Всецарица! Ты за меня упроси, Ты за меня умоли, дабы я прославлял(-а) преславное имя Твое всегда, ныне и в бесконечные века. Аминь."},
  {"id": "ru-mol-0577", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Всецарица» (Пантанасса). Молитва 2-я43"},
  {"id": "ru-mol-0578", "section": "service", "who": "rubric", "text": "О Пречистая Богомати, Всецарице! Услыши многоболезненное воздыхание наше пред чудотворною иконою Твоею, из удела Афонскаго в Россию пренесенною, призри на чад Твоих, неисцельными недуги страждущих и ко святому образу Твоему с верою припадающих!"},
  {"id": "ru-mol-0579", "section": "service", "who": "reader", "text": "О Пречистая Богоматерь, Всецарица! Услышь многоскорбный стон наш пред чудотворной иконой Твоей, из удела Афонского в Россию принесенной, воззри на чад Твоих, неисцелимыми недугами страдающих, ко святому образу Твоему с верою припадающих!"},
  {"id": "ru-mol-0580", "section": "service", "who": "reader", "text": "Как птица крылами покрывает птенцов своих, так ныне и Ты, вечно живая, покрой нас многоцелебным Твоим омофором. Там, где надежда исчезает, будь Надеждой, чуждою сомнений. Там, где лютые скорби превознемогают, Терпением и Облегчением для нас явись. Там, где мрак отчаяния в души вселился, да воссияет неизреченный свет Божества! Малодушных утешь, немощных укрепи, ожесточенным сердцам умягчение и просвещение даруй."},
  {"id": "ru-mol-0581", "section": "service", "who": "reader", "text": "Исцели болящих людей Твоих, о Всемилостивая Царица! Ум и руки врачующих нас благослови, да послужат они орудием Всемогущего Врача Христа, Спасителя нашего."},
  {"id": "ru-mol-0582", "section": "service", "who": "reader", "text": "Тебе как живой, находящейся здесь, с нами, молимся пред иконою Твоею, о Владычица! Простри руки Твои, исполненные исцелений и врачеваний, Радость скорбящих, в печалях Утешение, дабы мы, чудотворную помощь скоро получив, прославляли Живоначальную Нераздельную Троицу, Отца, Сына, и Святого Духа во веки веков. Аминь."},
  {"id": "ru-mol-0583", "section": "service", "who": "rubric", "text": "^ Пресвятой Богородице в честь Ее иконы «Скоропослушница»"},
  {"id": "ru-mol-0584", "section": "service", "who": "rubric", "text": "Тропарь, глас 4-й:44"},
  {"id": "ru-mol-0585", "section": "service", "who": "rubric", "text": "К Богородице притецем, сущии в бедах,/ и святей иконе Ея ныне припадем,/ с верою зовуще из глубины души:/ скоро наше услыши моление, Дево,/ яко Скоропослушница нарекшаяся,/ Тебе бо раби Твои в нуждах// готовую Помощницу имамы."},
  {"id": "ru-mol-0586", "section": "service", "who": "reader", "text": "К Богородице обратимся, находящиеся в бедах, и у святой иконы Ее сейчас преклоним колени, с верой взывая из глубины души: «Поскорее услышь нашу молитву, Дева, так как зовешься Скоропослушницей, поскольку Ты быстрая Помощница в скорбях для рабов Твоих»."},
  {"id": "ru-mol-0587", "section": "service", "who": "rubric", "text": "Кондак, глас 8-й:"},
  {"id": "ru-mol-0588", "section": "service", "who": "rubric", "text": "В мори житейстем обуреваемии,/ треволнению подпадаем страстей и искушений./ Подаждь убо нам, Госпоже, руку помощи, якоже Петрови Сын Твой,/ и ускори от бед избавити ны, да зовем Ти:// радуйся, всеблагая Скоропослушнице."},
  {"id": "ru-mol-0589", "section": "service", "who": "reader", "text": "В бурном море житейском мы попадаем в штормы страстей и искушений. Подай же нам, Госпожа, руку помощи, как Петру Сын Твой (Мф.14:28-31), и поспеши от бед избавить нас, да взываем к Тебе: «Радуйся, всеблагая Скоропослушница»."},
  {"id": "ru-mol-0590", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0591", "section": "service", "who": "rubric", "text": "Преблагословенная Владычице, Приснодево Богородице, Бога Слова паче всякаго слова на спасение наше рождшая, и благодать Его преизобильно паче всех приявшая, море явльшаяся Божественных дарований и чудес приснотекущая река, изливающая благость всем, с верою к Тебе прибегающим!"},
  {"id": "ru-mol-0592", "section": "service", "who": "reader", "text": "Преблагословенная Владычица, Приснодева Богородица, Бога-Слово выше всякого слова на спасение нам родившая, и благодать Его преизобильно более всех принявшая, явившаяся морем Божественных дарований и чудес вечно текущая река, изливающая благость всем, с верою к Тебе прибегающим!"},
  {"id": "ru-mol-0593", "section": "service", "who": "reader", "text": "К чудотворному Твоему образу припадая, молимся Тебе, всещедрой Матери Человеколюбивого Владыки: дивно яви на нас изобильные милости Твои, и прошения наши, приносимые Тебе, Скоропослушница, скоро исполни, устраивая все, что служит каждому на пользу, во утешение и спасение."},
  {"id": "ru-mol-0594", "section": "service", "who": "reader", "text": "Посети, Преблагая, рабов Твоих благодатию Твоею, подай недужным исцеление и совершенное здравие, охваченным бурей – тишину, пленным – свободу и различным образом страждущих утешь. Избавь, всемилостивая Госпожа, всякий город и страну от голода, язвы, землетрясения, потопа, огня, меча и иного наказания временного и вечного, Материнским Твоим дерзновением отвращая гнев Божий; и от душевного расслабления, бури страстей и грехопадений освободи рабов Твоих, чтобы без преткновения во всяком благочестии пожив в нынешнем веке, и в будущем вечных благ сподобимся по благодати и человеколюбию Сына Твоего и Бога, Которому подобает всякая слава, честь и поклонение, со Безначальным Его Отцом и Пресвятым Духом, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0595", "section": "service", "who": "rubric", "text": "^ Святителю Нектарию Эгинскому"},
  {"id": "ru-mol-0596", "section": "service", "who": "rubric", "text": "Тропарь, глас 1-й:"},
  {"id": "ru-mol-0597", "section": "service", "who": "rubric", "text": "Силиврии отрасль и Эгины хранителя, в последняя лета явльшагося, добродетели друга искренняго, Нектария почтим вернии, яко божественнаго служителя Христова: точит бо цельбы многоразличныя благочестно вопиющим: слава прославльшему тя Христу, слава давшему ти чудес благодать, слава действующему тобою всем исцеления."},
  {"id": "ru-mol-0598", "section": "service", "who": "reader", "text": "Селибрии росток и Эгины хранителя, в последние времена нам явившегося, близкого друга добродетели, Нектария почтим верующие, как священнослужителя Христова, ибо он источает многоразличные исцеления благочестиво взывающим: «Слава прославившему тебя Христу, слава Давшему тебе чудес благодать, слава Подающему через тебя всем исцеления»."},
  {"id": "ru-mol-0599", "section": "service", "who": "rubric", "text": "Кондак, глас 2-й:46"},
  {"id": "ru-mol-0600", "section": "service", "who": "rubric", "text": "Божественный гром, труба духовная, веры насадителю и отсекателю ересей, Троицы угодниче, великий святителю Нектарие, со Ангелы предстоя присно, моли непрестанно о всех нас."},
  {"id": "ru-mol-0601", "section": "service", "who": "reader", "text": "Божественный гром, труба духовная, веры насадитель и отсекатель ересей, Троицы угодник, великий святитель Нектарий, с Ангелами всегда предстоя, моли непрестанно обо всех нас."},
  {"id": "ru-mol-0602", "section": "service", "who": "rubric", "text": "Молитва:"},
  {"id": "ru-mol-0603", "section": "service", "who": "rubric", "text": "О святителю Нектарие, отче Богомудрый! Приими, блюстителю веры православныя, исповедание устен людей христоименитых, собранных днесь в храме благодатию Божиею, в тебе живущею. Весть бо достиже до предел Российских, яко ты, велий во святых угодниче Христов, во всех концех вселенныя призывающим имя твое являешися и от раковыя болезни исцеление даруеши."},
  {"id": "ru-mol-0604", "section": "service", "who": "reader", "text": "О святитель Нектарий, Богомудрый отец! Прими, блюститель православный веры, исповедание из уст людей, носящих имя Христа, собранных сегодня в храме Божьей благодатью, которая и в тебе живёт. Весть достигла пределов России, что ты, о великий среди святых угодник Христов, во всех концах вселенной призывающим имя твоё являешься и даруешь исцеление от раковых болезней."},
  {"id": "ru-mol-0605", "section": "service", "who": "reader", "text": "Мы слышали об иерее, соимённом тебе и строившем храм во имя твоё с великими тяготами. Он был поражён раком груди, кровь каждый день источал и тяжело страдал, но дела же своего святого не оставлял. Внезапно ты, святитель многомилостивый, с Неба сошел, и ему в храме предстал в видимом образе. Он же, приняв тебя за одного из смертных собратьев, просил молитв твоих и сказал: «Я сильно болею, но хочу святой алтарь построить, да по крайней мере один раз святую Литургию вместе с прихожанами совершить; после и умереть я готов, смерти не боюсь». Ты, отче, бесплотный, своё лицо слезами оросил и обнял страдальца, лобызая и говоря: «Не скорби, моё чадо, потому что ты, испытан болезнью, будешь здоров. Все об этом чуде будут знать». Он, исцелившись, тотчас понял, с кем беседовал, когда ты уже сделался невидимым."},
  {"id": "ru-mol-0606", "section": "service", "who": "reader", "text": "О великий угодник Христов Нектарий! Храм тот ныне стоит, и чудеса твои, как море разливающееся, умножается! Мы же узнали, что усиленной молитве праведника (Иак. 5:16) должно содействовать нашим усердием в службе Божией и решимостью умирать за Христа, да здоровье в этом обретём. Молят тебя, отче праведный, больные твои чада: да исполнится на нас Божья воля, благая, угодная и совершенная, не желающая смерти грешника, но чтобы он обратился и жил (Иез. 33:11). Ты же, провозвестник Божьей воли, исцели нас благодатным своим явлением, да будет велик Бог на Небесах и на земле во веки веков! Аминь."},
  {"id": "ru-mol-0607", "section": "service", "who": "rubric", "text": "Молитвы об исцелении болящего"},
  {"id": "ru-mol-0608", "section": "service", "who": "rubric", "text": "^ Молитва 1-я47"},
  {"id": "ru-mol-0609", "section": "service", "who": "rubric", "text": "Владыко, Вседержителю, святый Царю, наказуяй и не умерщвляяй, утверждаяй низпадающия и возводяй низверженныя, телесныя человеков скорби исправляяй, молимся Тебе, Боже наш, раба Твоего (имя) немощствующа посети милостию Твоею, прости ему всякое согрешение вольное и невольное."},
  {"id": "ru-mol-0610", "section": "service", "who": "reader", "text": "Владыка Вседержитель, святой Царь, наказывающий и не умерщвляющий, поддерживающий падающих и поднимающий поверженных, телесные скорби человеческие утоляющий, молимся к Тебе, Боже наш, раба Твоего (рабу Твою) (имя) немоществующего (-ую) посети Твоей милостью, прости ему (ей) всякое согрешение вольное и невольное."},
  {"id": "ru-mol-0611", "section": "service", "who": "reader", "text": "О Господи, врачебную Твою силу с небес ниспошли, коснись тела, угаси горячку, облегчи страдание и всякий скрытый недуг, стань врачом рабу Твоему (рабе Твоей) (имя), воздвигни его (её) с одра мучительного и с ложа страдания здравым и невредимым (здравой и невредимой), даруй его (её) Церкви Твоей угождающим (-ей) и исполняющим (-ей) волю Твою. Ибо Ты милуешь и спасаешь нас, Боже наш, и Тебе славу воссылаем, Отцу и Сыну и Святому Духу, ныне и всегда, и во веки веков. Аминь."},
  {"id": "ru-mol-0612", "section": "service", "who": "rubric", "text": "^ Молитва 2-я"},
  {"id": "ru-mol-0613", "section": "service", "who": "rubric", "text": "О Премилосердый Боже, Отче, Сыне и Святый Душе, в Нераздельней Троице покланяемый и славимый, призри благоутробно на раба Твоего (имя), болезнию одержимаго; отпусти ему вся согрешения его; подай ему исцеление от болезни; возврати ему здравие и силы телесные; подай ему долгоденственное и благоденственное житие, мирныя Твои и премирныя блага, чтобы он вместе с нами приносил благодарныя мольбы Тебе, Всещедрому Богу и Создателю нашему."},
  {"id": "ru-mol-0614", "section": "service", "who": "reader", "text": "О Премилосердный Боже, Отец, Сын и Святой Дух, Которому поклоняются и славят в Нераздельной Троице, с милостью обрати Своё внимание на раба Твоего (рабу Твою) (имя), одержимого (-ую) болезнью; отпусти ему (ей) все его (её) согрешения; подай ему (ей) исцеление от болезни; возврати ему (ей) здоровье и силы телесные; подай ему (ей) долгую и благую жизнь, отмирные Твои и неотмирные блага, чтобы он (она) вместе с нами приносил (-а) благодарные молитвы Тебе, Всещедрому Богу и Создателю нашему."},
];

